function initializeWordCards() {
    console.log('Initializing all word cards to be visible...');
    
    // Make all word cards in all categories visible by default
    document.querySelectorAll('.category-content').forEach(category => {
        const wordCards = category.querySelectorAll('.word-card');
        console.log(`Category ${category.id}: Making ${wordCards.length} word cards visible`);
        
        wordCards.forEach((card, index) => {
            // Force visibility by default - like Nature
            card.style.display = 'block';
            card.style.opacity = '1';
            card.style.visibility = 'visible';
            card.style.position = 'relative';
            card.style.pointerEvents = 'auto';
            
            // Ensure child elements are visible
            const emoji = card.querySelector('.word-emoji');
            const text = card.querySelector('.word-text');
            const sound = card.querySelector('.word-sound');
            
            if (emoji) {
                emoji.style.display = 'block';
                emoji.style.visibility = 'visible';
                emoji.style.opacity = '1';
            }
            
            if (text) {
                text.style.display = 'block';
                text.style.visibility = 'visible';
                text.style.opacity = '1';
            }
            
            if (sound) {
                sound.style.display = 'block';
                sound.style.visibility = 'visible';
                sound.style.opacity = '1';
            }
        });
    });
}

function selectWord(word, element) {
    if (!word) return;
    
    // Play sound if available
    playWordSound(word);
    
    // Update UI
    document.querySelectorAll('.word-card').forEach(card => {
        card.classList.remove('selected');
    });
    element.classList.add('selected');
    
    // Update current word
    currentWord = word;
    
    // Show learning feedback
    showLearningFeedback(word);
}

function playWordSound(word) {
    if (!word || !word.sound) return;
    
    // Create audio context
    const audioContext = new (window.AudioContext || window.webkitAudioContext)();
    
    // Create oscillator for simple sound
    const oscillator = audioContext.createOscillator();
    const gainNode = audioContext.createGain();
    
    oscillator.connect(gainNode);
    gainNode.connect(audioContext.destination);
    
    // Set frequency based on word (simple mapping)
    const frequency = getWordFrequency(word);
    oscillator.frequency.setValueAtTime(frequency, audioContext.currentTime);
    oscillator.type = 'sine';
    
    // Play short sound
    gainNode.gain.setValueAtTime(0.3, audioContext.currentTime);
    gainNode.gain.exponentialRampToValueAtTime(0.01, audioContext.currentTime + 0.3);
    
    oscillator.start(audioContext.currentTime);
    oscillator.stop(audioContext.currentTime + 0.3);
}

function getWordFrequency(word) {
    // Simple frequency mapping based on word length
    const baseFreq = 440;
    const multiplier = (word.name.length % 10) + 1;
    return baseFreq * multiplier;
}

function showLearningFeedback(word) {
    // Update baby mood
    updateBabyMood();
    
    // Show feedback message
    const feedback = babyMessages[babyMood][Math.floor(Math.random() * babyMessages[babyMood].length)];
    showNotification(feedback, 'success');
    
    // Update stats
    wordsLearned++;
    updateGameStats();
}

function updateBabyMood() {
    // Change mood based on time and interactions
    const timeSinceLastPlay = Date.now() - lastPlayTime;
    
    if (timeSinceLastPlay > 30000) { // 30 seconds
        babyMood = 'sleepy';
    } else if (Math.random() > 0.7) {
        babyMood = 'excited';
    } else {
        babyMood = 'happy';
    }
    
    lastPlayTime = Date.now();
}

function updateGameStats() {
    // Update stars
    if (wordsLearned % 5 === 0) {
        totalStars++;
        streak++;
    }
    
    // Save to localStorage
    localStorage.setItem('babble_stats', JSON.stringify({
        wordsLearned,
        totalStars,
        streak,
        babyMood
    }));
}

