// Play word function for babble game
function playWord(word, emoji) {
    // Create audio context for sound synthesis
    if ('speechSynthesis' in window) {
        const utterance = new SpeechSynthesisUtterance(word);
        utterance.lang = 'en-US';
        utterance.rate = 0.8;
        utterance.pitch = 1.2;
        utterance.volume = 1.0;
        
        // Cancel any previous speech
        window.speechSynthesis.cancel();
        
        // Speak the word
        window.speechSynthesis.speak(utterance);
        
        // Visual feedback
        const wordCards = document.querySelectorAll('.word-card');
        wordCards.forEach(card => {
            if (card.textContent.includes(word)) {
                card.style.transform = 'scale(1.1)';
                card.style.background = 'var(--primary-pink)';
                setTimeout(() => {
                    card.style.transform = 'scale(1)';
                    card.style.background = '';
                }, 500);
            }
        });
        
        // Update mini-game focus if on voice game
        const voiceTargetWord = document.getElementById('voiceTargetWord');
        if (voiceTargetWord) {
            voiceTargetWord.textContent = `Great! Now say "${word.charAt(0).toUpperCase() + word.slice(1)}"!`;
        }
    }
}

// Advanced AI Games with Groq API Integration
let recognition = null;
let isListening = false;
let voiceGameScore = 0;
let voiceGameStreak = 0;

// Groq AI API Configuration
const GROQ_API_KEY = 'gsk_your_api_key_here'; // Replace with actual API key
const GROQ_API_URL = 'https://api.groq.com/openai/v1/chat/completions';
const USE_MOCK_RESPONSES = GROQ_API_KEY === 'gsk_your_api_key_here'; // Use mock responses when API key is not set

// AI Game State Management
const aiGameState = {
    development: { isAnalyzing: false, lastAnalysis: null },
    lullaby: { isGenerating: false, lastLullaby: null },
    mood: { isAnalyzing: false, lastAnalysis: null },
    feeding: { isGenerating: false, lastSchedule: null },
    sleep: { isAnalyzing: false, lastAnalysis: null }
};

// Generic Groq API Call Function
async function callGroqAPI(messages, temperature = 0.7, maxTokens = 500) {
    // Use mock responses if API key is not configured
    if (USE_MOCK_RESPONSES) {
        return getMockResponse(messages);
    }

    try {
        const response = await fetch(GROQ_API_URL, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${GROQ_API_KEY}`
            },
            body: JSON.stringify({
                model: 'llama3-70b-8192',
                messages: messages,
                temperature: temperature,
                max_tokens: maxTokens,
                top_p: 1,
                stream: false
            })
        });

        if (!response.ok) {
            throw new Error(`Groq API error: ${response.status} - ${response.statusText}`);
        }

        const data = await response.json();
        return data.choices[0].message.content;
    } catch (error) {
        console.error('Groq API call failed:', error);
        throw error;
    }
}

// Mock Response Generator for Demo Mode
function getMockResponse(messages) {
    const userMessage = messages[messages.length - 1].content.toLowerCase();
    
        
    // Sleep Pattern Analyzer Mock Responses
    if (userMessage.includes('sleep') || userMessage.includes('sleeps')) {
        const hoursMatch = userMessage.match(/sleeps ([\d.]+) hours/);
        const sleepHours = hoursMatch ? hoursMatch[1] : '14';
        
        return `😴 Sleep Pattern Analysis: ${sleepHours} Hours Daily

📊 SLEEP ASSESSMENT:
Your baby's total sleep of ${sleepHours} hours is ${sleepHours >= 14 ? 'within the recommended range' : 'slightly below the recommended 14-17 hours'} for infants.

🎯 AGE-APPROPRIATE EXPECTATIONS:
• Total sleep: 14-17 hours per 24 hours
• Night sleep: 9-11 hours
• Daytime naps: 3-5 naps totaling 4-6 hours
• Awake windows: 1-2 hours between sleeps

🔍 ROOT CAUSES OF SLEEP ISSUES:
• Overtiredness from missed sleep windows
• Developmental milestones disrupting sleep
• Inconsistent bedtime routines
• Environmental factors (light, noise, temperature)
• Hunger or discomfort

🛠️ PERSONALIZED SLEEP TRAINING STRATEGIES:
1. **Establish Consistent Routine**: Bath → PJs → Feed → Story → Bed
2. **Create Sleep-Associations**: White noise, dark room, comfort object
3. **Watch Sleep Cues**: Yawning, eye rubbing, fussiness
4. **Practice Self-Soothing**: Allow brief fussing before intervening
5. **Consistent Wake Times**: Same wake-up time daily

🌙 BEDTIME ROUTINE RECOMMENDATIONS:
• Start 30-45 minutes before desired sleep time
• Dim lights and reduce stimulation
• Warm bath (10-15 minutes)
• Gentle massage with baby lotion
• Quiet activity (book, soft music)
• Final feeding in dim lighting
• Place in crib drowsy but awake

🏠 ENVIRONMENT OPTIMIZATION:
• Room temperature: 68-72°F (20-22°C)
• Blackout curtains or shades
• White noise machine or fan
• Firm, flat mattress with fitted sheet
• No loose bedding, toys, or bumpers

💤 NAP SCHEDULING:
• Morning nap: 1.5-2 hours after wake-up
• Afternoon nap: 2 hours after morning nap ends
• Late afternoon nap: Brief (45 minutes) if needed
• Avoid naps after 5 PM to protect bedtime

👩‍⚕️ WHEN TO SEEK HELP:
• Less than 9 hours total sleep daily
• Frequent night wakings (>3 times)
• Difficulty falling asleep (30+ minutes)
• Breathing irregularities during sleep
• Extreme fussiness around sleep times

Remember: Consistency is key to better sleep!`;
    }
    
    // Default mock response
    return `🤖 AI Response (Demo Mode)

This is a demonstration response. To get real AI-powered insights, please configure your Groq API key in the JavaScript file.

Current features available:
• Development milestone tracking
• Personalized lullaby generation
• Mood analysis and soothing strategies
• Feeding schedule optimization
• Sleep pattern analysis

To activate full AI functionality:
1. Get a free API key from https://groq.com
2. Replace 'gsk_your_api_key_here' with your actual key
3. Refresh the page to enjoy real AI responses!`;
}

// Update AI Status Indicator
function updateAIStatus(gameType, status, confidence = 0) {
    const statusElement = document.getElementById(`${gameType}Status`);
    const confidenceElement = document.getElementById(`${gameType}Confidence`);
    const confidenceTextElement = document.getElementById(`${gameType}ConfidenceText`);
    
    if (statusElement) {
        const statusText = statusElement.querySelector('span');
        if (statusText) {
            statusText.textContent = status;
        }
        
        const pulseElement = statusElement.querySelector('.ai-pulse');
        if (pulseElement) {
            if (status.includes('Analyzing') || status.includes('Generating')) {
                pulseElement.style.animation = 'pulse 1s infinite';
            } else {
                pulseElement.style.animation = 'pulse 2s infinite';
            }
        }
    }
    
    if (confidenceElement) {
        confidenceElement.style.width = `${confidence}%`;
    }
    
    if (confidenceTextElement) {
        confidenceTextElement.textContent = `${confidence}%`;
    }
}


// AI Sleep Pattern Analyzer
async function analyzeSleep() {
    if (aiGameState.sleep.isAnalyzing) {
        showNotification('Sleep analysis already in progress...', 'info');
        return;
    }

    const hoursInput = document.getElementById('sleepHours');
    const issuesSelect = document.getElementById('sleepIssues');
    const notesInput = document.getElementById('sleepNotes');
    const resultElement = document.getElementById('sleepResult');
    const feedbackElement = document.getElementById('sleepFeedback');

    const sleepHours = parseFloat(hoursInput.value) || null;
    const sleepIssues = issuesSelect.value;
    const notes = notesInput.value || 'No additional notes provided';

    if (!sleepHours) {
        showNotification('Please enter average sleep hours', 'warning');
        return;
    }

    aiGameState.sleep.isAnalyzing = true;
    updateAIStatus('sleep', 'Analyzing Sleep...', 40);
    resultElement.textContent = 'AI is analyzing your baby\'s sleep patterns...';
    feedbackElement.textContent = 'This may take a few moments...';

    try {
        const messages = [
            {
                role: 'system',
                content: `You are a pediatric sleep specialist and infant sleep expert. Analyze baby sleep patterns and provide personalized recommendations.
                
                Baby Sleep Information:
                - Average Sleep Hours: ${sleepHours} hours per day
                - Sleep Issues: ${sleepIssues}
                - Additional Notes: ${notes}
                
                Provide comprehensive sleep analysis including:
                1. Assessment of current sleep patterns
                2. Age-appropriate sleep expectations
                3. Root causes of sleep issues
                4. Personalized sleep training strategies
                5. Bedtime routine recommendations
                6. Environment optimization tips
                7. Nap schedule suggestions
                8. When to seek professional help
                
                Be practical, evidence-based, and supportive of both baby and parent wellbeing.`
            },
            {
                role: 'user',
                content: `Analyze the sleep patterns of a baby who sleeps ${sleepHours} hours per day with ${sleepIssues} issues. Additional context: ${notes}`
            }
        ];

        const analysis = await callGroqAPI(messages, 0.6, 600);
        
        aiGameState.sleep.lastAnalysis = analysis;
        resultElement.innerHTML = `<div style="white-space: pre-line; font-size: 14px; line-height: 1.5;">😴 ${analysis}</div>`;
        feedbackElement.textContent = 'Sleep analysis complete! Read recommendations above.';
        updateAIStatus('sleep', 'Analysis Complete', 92);
        
        showNotification('Sleep analysis completed successfully!', 'success');
        
    } catch (error) {
        console.error('Sleep analysis error:', error);
        resultElement.textContent = 'Analysis failed. Please try again.';
        feedbackElement.textContent = 'Error: Unable to connect to AI service. Please check your connection.';
        updateAIStatus('sleep', 'Error', 0);
        showNotification('Failed to analyze sleep. Please try again.', 'error');
    } finally {
        aiGameState.sleep.isAnalyzing = false;
    }
}

async function getSleepTips() {
    const hoursInput = document.getElementById('sleepHours');
    const resultElement = document.getElementById('sleepResult');
    const feedbackElement = document.getElementById('sleepFeedback');

    const sleepHours = parseFloat(hoursInput.value) || null;

    if (!sleepHours) {
        showNotification('Please enter average sleep hours first', 'warning');
        return;
    }

    aiGameState.sleep.isAnalyzing = true;
    updateAIStatus('sleep', 'Getting Tips...', 65);
    resultElement.textContent = 'AI is generating sleep tips...';

    try {
        const messages = [
            {
                role: 'system',
                content: `You are a pediatric sleep expert. Provide practical, evidence-based sleep tips for babies based on their current sleep patterns.
                
                Baby sleeps ${sleepHours} hours per day.
                
                Provide actionable sleep improvement strategies:
                1. Bedtime routine optimization
                2. Sleep environment improvements
                3. Nap scheduling tips
                4. Sleep training methods (gentle approaches)
                5. Common sleep problem solutions
                6. Parent sleep preservation strategies
                7. Developmental sleep considerations
                8. Safety guidelines
                
                Make tips specific to the sleep duration and easy to implement.`
            },
            {
                role: 'user',
                content: `Give me sleep improvement tips for a baby who sleeps ${sleepHours} hours per day.`
            }
        ];

        const tips = await callGroqAPI(messages, 0.7, 500);
        
        resultElement.innerHTML = `<div style="white-space: pre-line; font-size: 14px; line-height: 1.5;">💤 ${tips}</div>`;
        feedbackElement.textContent = 'Sleep tips ready! Implement these strategies for better rest.';
        updateAIStatus('sleep', 'Tips Ready', 88);
        
        showNotification('Sleep tips generated successfully!', 'success');
        
    } catch (error) {
        console.error('Sleep tips error:', error);
        resultElement.textContent = 'Failed to generate tips. Please try again.';
        updateAIStatus('sleep', 'Error', 0);
        showNotification('Failed to get sleep tips. Please try again.', 'error');
    } finally {
        aiGameState.sleep.isAnalyzing = false;
    }
}

