let currentSong = null;
let isPlaying = false;
let audioElement = null;
let currentAudioContext = null;

// Initialize Sleep Songs Library
function initializeSleepSongs() {
    audioElement = document.getElementById('songAudio');
    const songsList = document.getElementById('songsList');
    
    if (!songsList) return;
    
    // Populate songs list
    songsList.innerHTML = sleepSongs.map(song => `
        <div class="song-item" id="song-${song.id}" onclick="selectSong(${song.id})">
            <div class="song-title">${song.title}</div>
            <div class="song-artist">${song.artist}</div>
            <div class="song-duration">⏱️ ${song.duration}</div>
            <div class="song-preview">"${song.preview}"</div>
        </div>
    `).join('');
    
    // Set up audio event listeners
    audioElement.addEventListener('ended', () => {
        isPlaying = false;
        updatePlayPauseButton();
        playNextSong();
    });
    
    audioElement.addEventListener('error', () => {
        console.error('Audio playback error');
        showNotification('Audio playback error. Please try another song.', 'error');
    });
}

// Select and play a song
function selectSong(songId) {
    const song = sleepSongs.find(s => s.id === songId);
    if (!song) return;
    
    currentSong = song;
    
    // Update UI
    document.querySelectorAll('.song-item').forEach(item => {
        item.classList.remove('active');
    });
    document.getElementById(`song-${songId}`).classList.add('active');
    
    // Update now playing
    document.getElementById('nowPlaying').textContent = `🎵 Now Playing: ${song.title} - ${song.artist}`;
    
    // Load and play audio
    loadAndPlaySong(song);
}

// Load and play song audio
function loadAndPlaySong(song) {
    if (!audioElement) return;
    
    // For demo purposes, we'll use text-to-speech for lyrics
    // In production, you would load actual audio files
    playSongWithTextToSpeech(song);
}

// Play song using Web Audio API for real instrument tones
function playSongWithTextToSpeech(song) {
    if ('AudioContext' in window || 'webkitAudioContext' in window) {
        // Cancel any ongoing audio
        stopAudio();
        
        // Create audio context
        const AudioContextClass = window.AudioContext || window.webkitAudioContext;
        currentAudioContext = new AudioContextClass();
        
        // Set up audio nodes
        const gainNode = currentAudioContext.createGain();
        gainNode.connect(currentAudioContext.destination);
        gainNode.gain.value = 0.3; // Gentle volume
        
        // Play the lullaby melody
        playLullabyMelody(song, currentAudioContext, gainNode);
        
        isPlaying = true;
        updatePlayPauseButton();
        updateAIStatus('songs', 'Playing Song', 80);
        showNotification(`🎵 Playing: ${song.title}`, 'info');
        
        // Schedule song end
        const songDuration = getSongDuration(song);
        setTimeout(() => {
            isPlaying = false;
            updatePlayPauseButton();
            updateAIStatus('songs', 'Song Complete', 90);
            if (currentAudioContext) {
                currentAudioContext.close();
                currentAudioContext = null;
            }
            playNextSong();
        }, songDuration);
        
    } else {
        showNotification('Audio not supported in your browser', 'warning');
        // Show lyrics as fallback
        showLyrics(song);
    }
}

