// Note frequencies in Hz
const noteFrequencies = {
    'C4': 261.63, 'D4': 293.66, 'E4': 329.63, 'F4': 349.23,
    'G4': 392.00, 'A4': 440.00, 'B4': 493.88, 'C5': 523.25
};

// Play lullaby melody using Web Audio API
function playLullabyMelody(song, audioContext, gainNode) {
    const melody = lullabyMelodies[song.id] || lullabyMelodies[1];
    let currentTime = audioContext.currentTime;
    
    // Play extended melody once (now 1+ minute long)
    melody.forEach(note => {
        // Validate note data
        if (!note || !note.note || !noteFrequencies[note.note]) {
            console.error('Invalid note data:', note);
            return;
        }
        
        const frequency = noteFrequencies[note.note];
        const duration = note.duration;
        
        // Only play valid notes
        if (isFinite(frequency) && isFinite(duration) && frequency > 0 && duration > 0) {
            playNote(audioContext, gainNode, frequency, currentTime, duration);
            currentTime += duration / 1000;
        } else {
            console.error('Invalid note parameters:', { frequency, duration });
        }
    });
}

// Play a single piano note
function playNote(audioContext, gainNode, frequency, startTime, duration) {
    // Validate frequency value
    if (!isFinite(frequency) || frequency <= 0) {
        console.error('Invalid frequency value:', frequency);
        return;
    }
    
    // Validate duration value
    if (!isFinite(duration) || duration <= 0) {
        console.error('Invalid duration value:', duration);
        return;
    }
    
    // Create piano-like sound using multiple oscillators
    const fundamental = audioContext.createOscillator();
    const harmonic2 = audioContext.createOscillator();
    const harmonic3 = audioContext.createOscillator();
    
    // Set up fundamental frequency
    fundamental.type = 'triangle';
    fundamental.frequency.setValueAtTime(frequency, startTime);
    
    // Add harmonics for piano richness
    harmonic2.type = 'triangle';
    harmonic2.frequency.setValueAtTime(frequency * 2, startTime);
    
    harmonic3.type = 'sine';
    harmonic3.frequency.setValueAtTime(frequency * 3, startTime);
    
    // Create piano-like envelope (attack, sustain, release)
    const envelope = audioContext.createGain();
    envelope.gain.setValueAtTime(0, startTime);
    envelope.gain.linearRampToValueAtTime(0.3, startTime + 0.02); // Quick attack
    envelope.gain.exponentialRampToValueAtTime(0.2, startTime + 0.1); // Decay
    envelope.gain.setValueAtTime(0.2, startTime + duration/1000 - 0.1); // Sustain
    envelope.gain.exponentialRampToValueAtTime(0.01, startTime + duration/1000); // Release
    
    // Create mixer for harmonics
    const harmonicGain = audioContext.createGain();
    harmonicGain.gain.setValueAtTime(0.3, startTime); // Harmonic volume
    
    // Connect oscillators to mixer
    fundamental.connect(envelope);
    harmonic2.connect(harmonicGain);
    harmonic3.connect(harmonicGain);
    
    // Connect to envelope and gain
    harmonicGain.connect(envelope);
    envelope.connect(gainNode);
    
    // Schedule notes
    fundamental.start(startTime);
    fundamental.stop(startTime + duration/1000);
    harmonic2.start(startTime);
    harmonic2.stop(startTime + duration/1000);
    harmonic3.start(startTime);
    harmonic3.stop(startTime + duration/1000);
}

// Get song duration in milliseconds
function getSongDuration(song) {
    const melody = lullabyMelodies[song.id] || lullabyMelodies[1];
    const totalDuration = melody.reduce((sum, note) => sum + note.duration, 0);
    return totalDuration; // Extended melodies are now 1+ minute long
}

// Show lyrics as fallback
function showLyrics(song) {
    const lyricsHtml = `
        <div style="background: white; padding: 20px; border-radius: 10px; border: 2px solid #e8f4fd; margin-top: 15px;">
            <h4 style="color: #667eea; margin-bottom: 15px;">🎵 ${song.title} - ${song.artist}</h4>
            <p style="white-space: pre-line; line-height: 1.6; font-style: italic; color: #555;">${song.lyrics}</p>
            <p style="margin-top: 15px; font-size: 12px; color: #999;">Sing these lyrics to your baby ❤️</p>
        </div>
    `;
    
    const playerContainer = document.querySelector('.audio-player');
    if (playerContainer) {
        playerContainer.insertAdjacentHTML('afterend', lyricsHtml);
    }
}

// Toggle play/pause
function togglePlayPause() {
    if (!currentSong) {
        showNotification('Please select a song first', 'warning');
        return;
    }
    
    if (isPlaying) {
        pauseAudio();
    } else {
        resumeAudio();
    }
}

// Pause audio
function pauseAudio() {
    // For Web Audio API, we'll stop and restart from current position
    if (currentAudioContext) {
        currentAudioContext.suspend();
        isPlaying = false;
        updatePlayPauseButton();
        updateAIStatus('songs', 'Paused', 50);
    }
}

// Resume audio
function resumeAudio() {
    if (currentAudioContext) {
        currentAudioContext.resume();
        isPlaying = true;
        updatePlayPauseButton();
        updateAIStatus('songs', 'Playing', 80);
    }
}

// Stop audio
function stopAudio() {
    if (currentAudioContext) {
        currentAudioContext.close();
        currentAudioContext = null;
    }
    if ('speechSynthesis' in window) {
        window.speechSynthesis.cancel();
    }
    isPlaying = false;
    currentSong = null;
    updatePlayPauseButton();
    document.getElementById('nowPlaying').textContent = 'No song selected';
    document.querySelectorAll('.song-item').forEach(item => {
        item.classList.remove('active');
    });
    updateAIStatus('songs', 'Stopped', 0);
}

// Change volume
function changeVolume(value) {
    if (audioElement) {
        audioElement.volume = value / 100;
    }
}

// Update play/pause button
function updatePlayPauseButton() {
    const button = document.getElementById('playPauseBtn');
    if (button) {
        button.textContent = isPlaying ? '⏸️ Pause' : '▶️ Play';
    }
}

// Play next song automatically
function playNextSong() {
    if (!currentSong) return;
    
    const currentIndex = sleepSongs.findIndex(s => s.id === currentSong.id);
    const nextIndex = (currentIndex + 1) % sleepSongs.length;
    const nextSong = sleepSongs[nextIndex];
    
    // Auto-play next song after 2 seconds
    setTimeout(() => {
        selectSong(nextSong.id);
    }, 2000);
}

// Initialize sleep songs when page loads
document.addEventListener('DOMContentLoaded', () => {
    setTimeout(() => {
        initializeSleepSongs();
    }, 1000);
});

// Test if speech recognition service is accessible
function testSpeechRecognitionService() {
    console.log('Testing speech recognition service...');
    return new Promise((resolve) => {
        const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
        console.log('Creating test recognition instance...');
        
        try {
            const testRecognition = new SpeechRecognition();
            console.log('Test recognition created successfully');
            
            testRecognition.continuous = false;
            testRecognition.interimResults = false;
            testRecognition.maxAlternatives = 1;
            
            const timeout = setTimeout(() => {
                console.log('Service test timeout');
                testRecognition.abort();
                resolve(false); // Service timeout
            }, 5000);
            
            testRecognition.onstart = () => {
                console.log('Service test started successfully');
                clearTimeout(timeout);
                testRecognition.abort();
                resolve(true); // Service accessible
            };
            
            testRecognition.onerror = (event) => {
                console.log('Service test error:', event.error);
                clearTimeout(timeout);
                resolve(event.error !== 'network'); // false if network error, true otherwise
            };
            
            console.log('Starting service test...');
            testRecognition.start();
        } catch (e) {
            console.error('Failed to create or start test recognition:', e);
            resolve(false); // Can't start recognition
        }
    });
}

// Start voice game function
function startVoiceGame() {
    console.log('Starting voice game...');
    
    // Check browser compatibility
    if (!('webkitSpeechRecognition' in window) && !('SpeechRecognition' in window)) {
        console.error('Speech recognition not supported in this browser');
        showNotification('Speech recognition is not supported in your browser. Please try Chrome or Edge.', 'error');
        return;
    }
    
    console.log('Browser supports speech recognition');
    
    // Check network connectivity
    if (!navigator.onLine) {
        console.error('No internet connection');
        showNotification('No internet connection. Speech recognition requires an active internet connection.', 'error');
        return;
    }
    
    console.log('Network connection available');
    
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    console.log('SpeechRecognition constructor:', SpeechRecognition);
    
    const voiceTargetWord = document.getElementById('voiceTargetWord');
    const voiceVisualizer = document.getElementById('voiceVisualizer');
    const startBtn = document.querySelector('button[onclick="startVoiceGame()"]');
    const stopBtn = document.querySelector('button[onclick="stopVoiceGame()"]');
    
    console.log('Voice game elements:', {
        voiceTargetWord: !!voiceTargetWord,
        voiceVisualizer: !!voiceVisualizer,
        startBtn: !!startBtn,
        stopBtn: !!stopBtn
    });
    
    if (!voiceTargetWord || !voiceVisualizer) {
        console.error('Voice game elements not found');
        showNotification('Voice game elements not found.', 'error');
        return;
    }
    
    // Test speech recognition service before starting
    showNotification('Testing speech recognition service...', 'info');
    voiceTargetWord.textContent = 'Testing speech recognition service...';
    voiceVisualizer.style.background = 'linear-gradient(45deg, #00b894, #7c3aed, #00b894)';
    
    testSpeechRecognitionService().then(isServiceAvailable => {
        console.log('Service test result:', isServiceAvailable);
        if (!isServiceAvailable) {
            console.log('Service not available, switching to text mode');
            showNotification('Speech recognition service unavailable. Switching to text input mode.', 'warning');
            setTimeout(() => {
                enableTextInputMode();
            }, 1000);
            return;
        }
        
        console.log('Service available, setting up voice game');
        // Service is available, proceed with setup
        setupVoiceGame(SpeechRecognition, voiceTargetWord, voiceVisualizer, startBtn, stopBtn);
    }).catch(error => {
        console.error('Service test error:', error);
        showNotification('Error testing speech recognition service. Switching to text input mode.', 'warning');
        setTimeout(() => {
            enableTextInputMode();
        }, 1000);
    });
}

// Enable text input mode as fallback for speech recognition
function enableTextInputMode() {
    const voiceTargetWord = document.getElementById('voiceTargetWord');
    const voiceVisualizer = document.getElementById('voiceVisualizer');
    const startBtn = document.querySelector('button[onclick="startVoiceGame()"]');
    const stopBtn = document.querySelector('button[onclick="stopVoiceGame()"]');
    
    if (!voiceTargetWord || !voiceVisualizer) return;
    
    // Create text input interface
    const textInputContainer = document.createElement('div');
    textInputContainer.id = 'textInputContainer';
    textInputContainer.style.cssText = `
        margin-top: 20px;
        padding: 20px;
        background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
        border-radius: 15px;
        box-shadow: 0 8px 32px rgba(31, 38, 135, 0.37);
        backdrop-filter: blur(4px);
        border: 1px solid rgba(255, 255, 255, 0.18);
    `;
    
    textInputContainer.innerHTML = `
        <h3 style="color: #2c3e50; margin-bottom: 15px; text-align: center;">📝 Text Input Mode</h3>
        <p style="color: #546e7a; text-align: center; margin-bottom: 20px;">Type the word you see below:</p>
        <div style="text-align: center; margin-bottom: 20px;">
            <span id="textTargetWord" style="font-size: 24px; font-weight: bold; color: #3498db; background: white; padding: 10px 20px; border-radius: 10px; box-shadow: 0 4px 6px rgba(0,0,0,0.1);"></span>
        </div>
        <div style="text-align: center; margin-bottom: 15px;">
            <input type="text" id="voiceTextInput" placeholder="Type the word here..." style="
                padding: 12px 20px;
                font-size: 16px;
                border: 2px solid #3498db;
                border-radius: 25px;
                width: 250px;
                outline: none;
                transition: all 0.3s ease;
            " onkeypress="if(event.key === 'Enter') checkTextInputAnswer()">
        </div>
        <div style="text-align: center;">
            <button onclick="checkTextInputAnswer()" style="
                background: linear-gradient(45deg, #3498db, #2980b9);
                color: white;
                border: none;
                padding: 12px 30px;
                border-radius: 25px;
                font-size: 16px;
                cursor: pointer;
                transition: all 0.3s ease;
                margin-right: 10px;
            ">Check Answer</button>
            <button onclick="retrySpeechRecognition()" style="
                background: linear-gradient(45deg, #00d4aa, #00d4aa);
                color: white;
                border: none;
                padding: 12px 30px;
                border-radius: 25px;
                font-size: 16px;
                cursor: pointer;
                transition: all 0.3s ease;
            ">Try Voice Again</button>
        </div>
        <div id="textFeedback" style="text-align: center; margin-top: 15px; font-weight: bold;"></div>
    `;
    
    // Replace the voice game area with text input
    const voiceGameArea = voiceTargetWord.parentElement;
    if (voiceGameArea) {
        voiceGameArea.appendChild(textInputContainer);
    }
    
    // Set initial target word
    const gameWords = ['cat', 'dog', 'duck', 'cow', 'bird', 'fish', 'apple', 'banana', 'milk', 'cookie', 'bread', 'juice', 'ball', 'book', 'teddy', 'car', 'blocks', 'crayon', 'clap', 'wave', 'jump', 'sleep', 'eat', 'play'];
    const initialTargetWord = gameWords[Math.floor(Math.random() * gameWords.length)];
    window.currentTargetWord = initialTargetWord;
    
    document.getElementById('textTargetWord').textContent = initialTargetWord.charAt(0).toUpperCase() + initialTargetWord.slice(1);
    
    // Update UI
    voiceTargetWord.textContent = 'Text input mode activated. Type the word shown above!';
    voiceVisualizer.style.background = 'linear-gradient(45deg, #00d4aa, #00d4aa, #00d4aa)';
    
    if (startBtn) startBtn.textContent = 'Switch to Voice';
    if (stopBtn) stopBtn.style.display = 'none';
    
    showNotification('Text input mode activated. You can type your answers instead of speaking!', 'success');
}

// Check text input answer
function checkTextInputAnswer() {
    const textInput = document.getElementById('voiceTextInput');
    const textFeedback = document.getElementById('textFeedback');
    const textTargetWord = document.getElementById('textTargetWord');
    
    if (!textInput || !textFeedback || !textTargetWord) return;
    
    const userAnswer = textInput.value.toLowerCase().trim();
    const correctAnswer = window.currentTargetWord.toLowerCase();
    
    if (userAnswer === correctAnswer) {
        // Correct answer
        voiceGameScore++;
        voiceGameStreak++;
        
        textFeedback.innerHTML = `🎉 Correct! Score: ${voiceGameScore} | Streak: ${voiceGameStreak}🔥`;
        textFeedback.style.color = '#00d4aa';
        
        // Generate new word
        setTimeout(() => {
            const gameWords = ['cat', 'dog', 'duck', 'cow', 'bird', 'fish', 'apple', 'banana', 'milk', 'cookie', 'bread', 'juice', 'ball', 'book', 'teddy', 'car', 'blocks', 'crayon', 'clap', 'wave', 'jump', 'sleep', 'eat', 'play'];
            const newWord = gameWords[Math.floor(Math.random() * gameWords.length)];
            window.currentTargetWord = newWord;
            textTargetWord.textContent = newWord.charAt(0).toUpperCase() + newWord.slice(1);
            textInput.value = '';
            textFeedback.textContent = '';
        }, 2000);
    } else {
        // Wrong answer
        voiceGameStreak = 0;
        textFeedback.innerHTML = `❌ Wrong! You typed "${textInput.value}". Try again!`;
        textFeedback.style.color = '#ff6b9d';
        textInput.value = '';
    }
    
    // Update score display
    const scoreValue = document.getElementById('voiceScoreValue');
    const streakValue = document.getElementById('voiceStreakValue');
    if (scoreValue) scoreValue.textContent = voiceGameScore;
    if (streakValue) streakValue.textContent = voiceGameStreak;
}

// Retry speech recognition
function retrySpeechRecognition() {
    const textInputContainer = document.getElementById('textInputContainer');
    if (textInputContainer) {
        textInputContainer.remove();
    }
    
    const startBtn = document.querySelector('button[onclick="startVoiceGame()"]');
    const stopBtn = document.querySelector('button[onclick="stopVoiceGame()"]');
    if (startBtn) startBtn.textContent = 'Start Listening';
    if (stopBtn) stopBtn.style.display = 'inline-block';
    
    window.networkRetryCount = 0; // Reset retry counter
    startVoiceGame();
}

function setupVoiceGame(SpeechRecognition, voiceTargetWord, voiceVisualizer, startBtn, stopBtn) {
    console.log('Setting up voice game...');
    
    // Store recognition instance globally
    recognition = new SpeechRecognition();
    console.log('Recognition instance created:', recognition);
    
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = 'en-US';
    console.log('Recognition configured:', {
        continuous: recognition.continuous,
        interimResults: recognition.interimResults,
        lang: recognition.lang
    });
    
    // Set initial target word
    const gameWords = ['cat', 'dog', 'duck', 'cow', 'bird', 'fish', 'apple', 'banana', 'milk', 'cookie', 'bread', 'juice', 'ball', 'book', 'teddy', 'car', 'blocks', 'crayon', 'clap', 'wave', 'jump', 'sleep', 'eat', 'play'];
    const initialTargetWord = gameWords[Math.floor(Math.random() * gameWords.length)];
    window.currentTargetWord = initialTargetWord;
    
    // Update UI
    if (startBtn) startBtn.disabled = true;
    if (stopBtn) stopBtn.disabled = false;
    
    // Show score display
    const scoreDisplay = document.getElementById('voiceScoreDisplay');
    if (scoreDisplay) {
        scoreDisplay.style.display = 'flex';
    }
    
    // Update score display elements
    const scoreValue = document.getElementById('voiceScoreValue');
    const streakValue = document.getElementById('voiceStreakValue');
    if (scoreValue) scoreValue.textContent = voiceGameScore;
    if (streakValue) streakValue.textContent = voiceGameStreak;
    
    // Update feedback and target word
    const voiceFeedback = document.getElementById('voiceFeedback');
    if (voiceFeedback) voiceFeedback.textContent = 'Listening... Speak clearly!';
    voiceTargetWord.textContent = `Say "${initialTargetWord.charAt(0).toUpperCase() + initialTargetWord.slice(1)}"!`;
    voiceVisualizer.style.background = 'linear-gradient(45deg, #ff6b9d, #667eea, #764ba2)';
    voiceVisualizer.style.animation = 'pulse 1s infinite';
    
    recognition.onresult = function(event) {
        const current = event.resultIndex;
        const transcript = event.results[current][0].transcript.toLowerCase().trim();
        const confidence = Math.round((event.results[current][0].confidence || 0) * 100);
        
        // Update confidence meter
        const confidenceFill = document.getElementById('confidenceFill');
        const confidenceText = document.getElementById('confidenceText');
        if (confidenceFill) confidenceFill.style.width = confidence + '%';
        if (confidenceText) confidenceText.textContent = confidence + '%';
        
        // Update AI status
        const aiStatus = document.getElementById('aiStatus');
        if (aiStatus) aiStatus.innerHTML = '<div class="ai-pulse"></div><span>Listening...</span>';
        
        if (event.results[current].isFinal) {
            // Check if spoken word matches current target word
            const currentTarget = window.currentTargetWord;
            
            if (transcript === currentTarget) {
                // Update score and streak
                voiceGameScore += 10;
                voiceGameStreak += 1;
                
                // Update score display
                const scoreValue = document.getElementById('voiceScoreValue');
                const streakValue = document.getElementById('voiceStreakValue');
                if (scoreValue) scoreValue.textContent = voiceGameScore;
                if (streakValue) streakValue.textContent = voiceGameStreak;
                
                voiceTargetWord.textContent = `🎉 Perfect! You said "${transcript}"! Score: ${voiceGameScore} | Streak: ${voiceGameStreak}🔥`;
                voiceVisualizer.style.background = 'linear-gradient(45deg, #00d2ff, #3a7bd5, #00d2ff)';
                
                // Update AI status
                if (aiStatus) aiStatus.innerHTML = '<div class="ai-pulse" style="background: #00d4aa;"></div><span>Correct! 🎉</span>';
                
                // Generate new target word after delay
                setTimeout(() => {
                    const gameWords = ['cat', 'dog', 'duck', 'cow', 'bird', 'fish', 'apple', 'banana', 'milk', 'cookie', 'bread', 'juice', 'ball', 'book', 'teddy', 'car', 'blocks', 'crayon', 'clap', 'wave', 'jump', 'sleep', 'eat', 'play'];
                    const newTargetWord = gameWords[Math.floor(Math.random() * gameWords.length)];
                    window.currentTargetWord = newTargetWord;
                    voiceTargetWord.textContent = `Now say "${newTargetWord.charAt(0).toUpperCase() + newTargetWord.slice(1)}"!`;
                    voiceVisualizer.style.background = 'linear-gradient(45deg, #ff6b9d, #667eea, #764ba2)';
                    if (aiStatus) aiStatus.innerHTML = '<div class="ai-pulse"></div><span>AI Ready</span>';
                }, 2000);
            } else {
                // Reset streak on wrong word
                voiceGameStreak = 0;
                
                // Update score display
                const scoreValue = document.getElementById('voiceScoreValue');
                const streakValue = document.getElementById('voiceStreakValue');
                if (scoreValue) scoreValue.textContent = voiceGameScore;
                if (streakValue) streakValue.textContent = voiceGameStreak;
                
                voiceTargetWord.textContent = `❌ Wrong! You said "${transcript}". Score: ${voiceGameScore} | Streak: ${voiceGameStreak}🔥. Try saying "${currentTarget.charAt(0).toUpperCase() + currentTarget.slice(1)}"!`;
                voiceVisualizer.style.background = 'linear-gradient(45deg, #ff8fab, #ff6b9d, #ff8fab)';
                
                // Update AI status
                if (aiStatus) aiStatus.innerHTML = '<div class="ai-pulse" style="background: #ff6b9d;"></div><span>Try Again</span>';
            }
        } else {
            voiceTargetWord.textContent = `Hearing: "${transcript}"...`;
        }
    };
    
    recognition.onerror = function(event) {
        console.error('Speech recognition error:', event.error);
        
        // Handle specific error cases
        if (event.error === 'no-speech') {
            voiceTargetWord.textContent = 'No speech detected. Try speaking clearly!';
            voiceVisualizer.style.background = 'linear-gradient(45deg, #ff9800, #ff527d, #ff9800)';
        } else if (event.error === 'network') {
            // Immediately switch to text input mode for network errors
            voiceTargetWord.textContent = 'Speech recognition unavailable. Switching to text input mode...';
            voiceVisualizer.style.background = 'linear-gradient(45deg, #9e9e9e, #757575, #9e9e9e)';
            showNotification('Speech recognition service unavailable. Switching to text input mode.', 'warning');
            
            // Re-enable start button
            if (startBtn) startBtn.disabled = false;
            if (stopBtn) stopBtn.disabled = true;
            
            // Switch to text input mode after a short delay
            setTimeout(() => {
                enableTextInputMode();
            }, 1000);
        } else if (event.error === 'not-allowed') {
            voiceTargetWord.textContent = 'Microphone access denied. Please allow microphone access and try again!';
            voiceVisualizer.style.background = 'linear-gradient(45deg, #ff9800, #ff527d, #ff9800)';
            showNotification('Please allow microphone access to use speech recognition.', 'error');
        } else if (event.error === 'service-not-allowed') {
            voiceTargetWord.textContent = 'Speech recognition service not available. Try refreshing the page!';
            voiceVisualizer.style.background = 'linear-gradient(45deg, #667eea, #7c3aed, #667eea)';
            showNotification('Speech recognition service is temporarily unavailable. Please try again later.', 'error');
        } else {
            voiceTargetWord.textContent = `Error: ${event.error}. Try again!`;
            voiceVisualizer.style.background = 'linear-gradient(45deg, #ff8fab, #ff6b9d, #ff8fab)';
        }
        
        // Re-enable start button
        if (startBtn) startBtn.disabled = false;
        if (stopBtn) stopBtn.disabled = true;
    };
    
    recognition.onend = function() {
        // Re-enable start button when recognition ends
        if (startBtn) startBtn.disabled = false;
        if (stopBtn) stopBtn.disabled = true;
        
        // Update UI
        voiceTargetWord.textContent = 'Listening stopped. Click "Start Listening" to try again!';
        voiceVisualizer.style.animation = '';
        voiceVisualizer.style.background = '';
        
        // Update AI status
        const aiStatus = document.getElementById('aiStatus');
        if (aiStatus) aiStatus.innerHTML = '<div class="ai-pulse"></div><span>AI Ready</span>';
        
        // Update confidence meter
        const confidenceFill = document.getElementById('confidenceFill');
        const confidenceText = document.getElementById('confidenceText');
        if (confidenceFill) confidenceFill.style.width = '0%';
        if (confidenceText) confidenceText.textContent = '0%';
        
        // Update feedback
        const voiceFeedback = document.getElementById('voiceFeedback');
        if (voiceFeedback) voiceFeedback.textContent = 'Click "Start Listening" to play again!';
    };
    
    // Start recognition
    console.log('Starting recognition...');
    try {
        recognition.start();
        console.log('Recognition started successfully');
        showNotification('Voice recognition started! Say a word from the game.', 'success');
    } catch (error) {
        console.error('Failed to start recognition:', error);
        showNotification('Failed to start voice recognition. Switching to text mode.', 'error');
        setTimeout(() => {
            enableTextInputMode();
        }, 1000);
    }
}

// Stop voice game function
function stopVoiceGame() {
    // Stop the recognition if it exists
    if (recognition) {
        recognition.stop();
        recognition = null;
    }
    
    const voiceTargetWord = document.getElementById('voiceTargetWord');
    const voiceVisualizer = document.getElementById('voiceVisualizer');
    const voiceFeedback = document.getElementById('voiceFeedback');
    const startBtn = document.querySelector('button[onclick="startVoiceGame()"]');
    const stopBtn = document.querySelector('button[onclick="stopVoiceGame()"]');
    
    // Update UI elements
    if (voiceTargetWord) {
        voiceTargetWord.textContent = 'Voice recognition stopped. Click "Start Listening" to play!';
    }
    
    if (voiceVisualizer) {
        voiceVisualizer.style.animation = '';
        voiceVisualizer.style.background = '';
    }
    
    if (voiceFeedback) {
        voiceFeedback.textContent = 'Game stopped. Click "Start Listening" to play again!';
    }
    
    // Update AI status
    const aiStatus = document.getElementById('aiStatus');
    if (aiStatus) aiStatus.innerHTML = '<div class="ai-pulse"></div><span>AI Ready</span>';
    
    // Reset confidence meter
    const confidenceFill = document.getElementById('confidenceFill');
    const confidenceText = document.getElementById('confidenceText');
    if (confidenceFill) confidenceFill.style.width = '0%';
    if (confidenceText) confidenceText.textContent = '0%';
    
    // Update buttons
    if (startBtn) startBtn.disabled = false;
    if (stopBtn) stopBtn.disabled = true;
    
    showNotification('Voice recognition stopped.', 'info');
}

