// Customize pregnancy topic content based on current week
function customizeTopicForWeek(topicKey, currentWeek, baseData) {
    const customizedData = { ...baseData };
    
    // Determine trimester
    let trimester = 'first';
    if (currentWeek > 13 && currentWeek <= 27) trimester = 'second';
    else if (currentWeek > 27) trimester = 'third';
    
    // Customize based on topic type and current week
    switch (topicKey) {
        case 'pregnancy-week-by-week':
            customizedData.summary = `Complete guide from week 1 to 40. You're currently in week ${currentWeek} - ${trimester} trimester.`;
            customizedData.actionNote = `Jump to week ${currentWeek} details in the roadmap below.`;
            break;
            
        case 'your-body':
            customizedData.forMom = `Your body is adapting to week ${currentWeek} of pregnancy. Focus on the changes happening right now.`;
            customizedData.checklist = getWeekSpecificChecklist('body', currentWeek);
            break;
            
        case 'symptoms':
            customizedData.summary = `Common symptoms for week ${currentWeek} and how to manage them effectively.`;
            customizedData.checklist = getWeekSpecificChecklist('symptoms', currentWeek);
            break;
            
        case 'fitness':
            customizedData.summary = `Safe exercises specifically recommended for week ${currentWeek} of ${trimester} trimester.`;
            customizedData.checklist = getWeekSpecificChecklist('fitness', currentWeek);
            break;
            
        case 'your-baby':
            customizedData.summary = `Your baby's development at week ${currentWeek} - size, milestones, and what to expect.`;
            customizedData.forBaby = `At week ${currentWeek}, your baby is ${getBabySizeDescription(currentWeek)} and developing rapidly.`;
            break;
            
        case 'healthy-eating':
            customizedData.summary = `Nutrition needs for week ${currentWeek} and foods that support current development stage.`;
            customizedData.checklist = getWeekSpecificChecklist('nutrition', currentWeek);
            break;
            
        case 'sleep':
            customizedData.summary = `Sleep challenges and solutions specific to week ${currentWeek} of pregnancy.`;
            customizedData.checklist = getWeekSpecificChecklist('sleep', currentWeek);
            break;
            
        case 'labor-delivery':
            if (currentWeek > 28) {
                customizedData.summary = `Preparing for birth! You're ${40 - currentWeek} weeks from your due date.`;
                customizedData.checklist = getWeekSpecificChecklist('labor', currentWeek);
            } else {
                customizedData.summary = `Birth planning overview. Start thinking about your preferences, though birth is still ${40 - currentWeek} weeks away.`;
            }
            break;
    }
    
    return customizedData;
}

// Get week-specific checklist items
function getWeekSpecificChecklist(type, week) {
    const checklists = {
        body: {
            early: ['Track weight gain', 'Monitor morning sickness', 'Rest frequently', 'Stay hydrated', 'Practice good posture'],
            mid: ['Monitor swelling', 'Practice stretching', 'Use support belts', 'Stay active', 'Monitor back pain'],
            late: ['Practice birth positions', 'Use pillows for support', 'Monitor contractions', 'Rest frequently', 'Prepare hospital bag']
        },
        symptoms: {
            early: ['Manage morning sickness', 'Track fatigue levels', 'Monitor food aversions', 'Handle mood changes', 'Rest when needed'],
            mid: ['Monitor round ligament pain', 'Track energy levels', 'Manage swelling', 'Monitor heartburn', 'Stay comfortable'],
            late: ['Monitor Braxton Hicks', 'Track back pain', 'Monitor shortness of breath', 'Manage pelvic pressure', 'Rest frequently']
        },
        fitness: {
            early: ['Walk 30 minutes daily', 'Practice prenatal yoga', 'Do gentle stretching', 'Swim if possible', 'Avoid heavy lifting'],
            mid: ['Continue walking', 'Add strength training', 'Practice pelvic tilts', 'Do pregnancy-safe exercises', 'Monitor intensity'],
            late: ['Practice birth squats', 'Do pelvic floor exercises', 'Practice breathing techniques', 'Gentle stretching', 'Prepare for labor']
        },
        nutrition: {
            early: ['Take prenatal vitamins', 'Eat small frequent meals', 'Focus on protein', 'Avoid certain foods', 'Stay hydrated'],
            mid: ['Increase calcium intake', 'Focus on iron-rich foods', 'Eat balanced meals', 'Monitor weight gain', 'Stay hydrated'],
            late: ['Increase fiber intake', 'Focus on small meals', 'Avoid heartburn triggers', 'Stay hydrated', 'Prepare postpartum nutrition']
        },
        sleep: {
            early: ['Sleep on left side', 'Use pillows for support', 'Establish routine', 'Limit fluids before bed', 'Create dark environment'],
            mid: ['Use pregnancy pillows', 'Elevate legs', 'Practice relaxation', 'Limit screen time', 'Stay comfortable'],
            late: ['Sleep in recliner if needed', 'Use multiple pillows', 'Practice breathing', 'Limit caffeine', 'Prepare for night feedings']
        },
        labor: {
            early: ['Research birth options', 'Find healthcare provider', 'Consider birth classes', 'Talk to partner about preferences', 'Start saving for birth'],
            mid: ['Take birth classes', 'Create birth plan', 'Tour hospital', 'Practice breathing', 'Pack preliminary hospital bag'],
            late: ['Finalize birth plan', 'Pack complete hospital bag', 'Install car seat', 'Arrange childcare', 'Practice labor positions']
        }
    };
    
    let period = 'early';
    if (week > 13 && week <= 27) period = 'mid';
    else if (week > 27) period = 'late';
    
    return checklists[type]?.[period] || checklists.body.early;
}

// Get baby size description for current week
function getBabySizeDescription(week) {
    const sizes = {
        1: 'the size of a poppy seed',
        4: 'the size of a blueberry', 
        8: 'the size of a raspberry',
        12: 'the size of a lime',
        16: 'the size of an avocado',
        20: 'the size of a banana',
        24: 'the size of an ear of corn',
        28: 'the size of an eggplant',
        32: 'the size of a pineapple',
        36: 'the size of a honeydew melon',
        40: 'the size of a watermelon'
    };
    
    // Find closest size
    const weeks = Object.keys(sizes).map(Number).sort((a, b) => a - b);
    for (let i = weeks.length - 1; i >= 0; i--) {
        if (week >= weeks[i]) {
            return sizes[weeks[i]];
        }
    }
    return sizes[1];
}

