function calculateAdvancedConception() {
    // Get input elements
    const dueDateInput = document.getElementById('conceptionDueDate');
    const lmpInput = document.getElementById('conceptionLMP');
    const cycleLengthInput = document.getElementById('conceptionCycleLength');
    const pregnancyTypeInput = document.getElementById('pregnancyType');
    const cycleRegularityInput = document.getElementById('cycleRegularity');
    
    // Get values
    const dueDate = dueDateInput?.value;
    const lmp = lmpInput?.value;
    const cycleLength = parseInt(cycleLengthInput?.value) || 28;
    const pregnancyType = pregnancyTypeInput?.value;
    const cycleRegularity = cycleRegularityInput?.value;
    
    let conceptionDate, estimatedDueDate, fertileWindowStart, fertileWindowEnd;
    let calculationMethod = '';
    
    // Check if due date is provided
    if (dueDate && dueDate.trim() !== '') {
        calculationMethod = 'due-date';
        const due = new Date(dueDate);
        if (isNaN(due.getTime())) {
            showNotification('Please enter a valid due date', 'error');
            return;
        }
        
        // Adjust calculation based on pregnancy type
        let daysToSubtract = 266;
        if (pregnancyType === 'twins') daysToSubtract = 263;
        if (pregnancyType === 'triplets') daysToSubtract = 260;
        
        conceptionDate = new Date(due.getTime() - (daysToSubtract * 24 * 60 * 60 * 1000));
        fertileWindowStart = new Date(conceptionDate.getTime() - (5 * 24 * 60 * 60 * 1000));
        fertileWindowEnd = new Date(conceptionDate.getTime() + (1 * 24 * 60 * 60 * 1000));
    } 
    // Check if LMP is provided
    else if (lmp && lmp.trim() !== '') {
        calculationMethod = 'lmp';
        const lastPeriod = new Date(lmp);
        if (isNaN(lastPeriod.getTime())) {
            showNotification('Please enter a valid last menstrual period date', 'error');
            return;
        }
        
        // Adjust ovulation day based on cycle length and regularity
        let ovulationDay = 14;
        if (cycleRegularity === 'very-irregular') ovulationDay = 16;
        if (cycleRegularity === 'irregular') ovulationDay = 15;
        if (cycleLength < 25) ovulationDay = 13;
        if (cycleLength > 32) ovulationDay = 16;
        
        conceptionDate = new Date(lastPeriod.getTime() + (ovulationDay * 24 * 60 * 60 * 1000));
        estimatedDueDate = new Date(lastPeriod.getTime() + (280 * 24 * 60 * 60 * 1000));
        fertileWindowStart = new Date(lastPeriod.getTime() + ((ovulationDay - 5) * 24 * 60 * 60 * 1000));
        fertileWindowEnd = new Date(lastPeriod.getTime() + ((ovulationDay + 4) * 24 * 60 * 60 * 1000));
    } 
    // No valid input provided
    else {
        showNotification('Please enter either due date or last menstrual period', 'warning');
        return;
    }
    
    // Generate AI analysis
    const aiAnalysis = generateAIConceptionAnalysis(calculationMethod, cycleLength, cycleRegularity, pregnancyType, conceptionDate, lmp);
    
    // Display results
    displayAdvancedConceptionResults(conceptionDate, estimatedDueDate, fertileWindowStart, fertileWindowEnd, dueDate, lmp, aiAnalysis);
}

function generateAIConceptionAnalysis(method, cycleLength, regularity, pregnancyType, conceptionDate, lmp) {
    const analysis = {
        method: method,
        accuracy: method === 'due-date' ? 'High' : 'Medium',
        factors: [],
        recommendations: [],
        fertilityScore: 0
    };
    
    if (method === 'due-date') {
        analysis.factors.push('Confirmed due date from medical provider');
        analysis.factors.push('Most accurate calculation method');
        analysis.fertilityScore = 95;
        analysis.recommendations.push('This is the most reliable method for conception dating');
        analysis.recommendations.push('Consider sharing this date with your healthcare provider');
    } else if (method === 'lmp') {
        analysis.factors.push(`Cycle length: ${cycleLength} days`);
        analysis.factors.push(`Cycle regularity: ${regularity}`);
        
        // Calculate fertility score based on cycle characteristics
        let score = 70;
        if (cycleLength >= 26 && cycleLength <= 32) score += 10;
        if (regularity === 'regular') score += 15;
        if (regularity === 'mostly-regular') score += 10;
        if (regularity === 'irregular') score -= 10;
        if (regularity === 'very-irregular') score -= 20;
        
        analysis.fertilityScore = Math.max(30, Math.min(95, score));
        
        analysis.recommendations.push('Track your cycle for 2-3 months for better accuracy');
        if (regularity !== 'regular') {
            analysis.recommendations.push('Consider lifestyle changes to improve cycle regularity');
        }
        analysis.recommendations.push('Use ovulation predictor kits for better timing');
    }
    
    if (pregnancyType === 'twins') {
        analysis.recommendations.push('Multiple pregnancies typically conceived earlier');
        analysis.recommendations.push('Consider earlier ultrasound for accurate dating');
    }
    
    return analysis;
}

