function checkPregnancySymptoms() {
    const daysPastOvulation = document.getElementById('symptomsDaysPastOvulation')?.value;
    const symptoms = Array.from(document.querySelectorAll('input[type="checkbox"]:checked')).map(cb => cb.value);
    
    if (!daysPastOvulation) {
        showNotification('Please select how many days past ovulation', 'warning');
        return;
    }
    
    if (symptoms.length === 0) {
        showNotification('Please select at least one symptom', 'warning');
        return;
    }
    
    const analysis = analyzePregnancySymptoms(daysPastOvulation, symptoms);
    displaySymptomsResults(analysis);
}

