function analyzePregnancySymptoms(daysPastOvulation, symptoms) {
    // Early pregnancy symptom scoring
    const earlySymptoms = {
        'missed-period': { weight: 3, early: true, very_early: false },
        'nausea': { weight: 2, early: true, very_early: false },
        'fatigue': { weight: 2, early: true, very_early: true },
        'tender-breasts': { weight: 2, early: true, very_early: true },
        'frequent-urination': { weight: 2, early: true, very_early: false },
        'food-cravings': { weight: 1, early: true, very_early: false },
        'mood-swings': { weight: 1, early: true, very_early: true },
        'bloating': { weight: 1, early: true, very_early: true },
        'light-spotting': { weight: 2, very_early: true, early: false },
        'headaches': { weight: 1, early: true, very_early: true },
        'dizziness': { weight: 1, early: true, very_early: true },
        'basal-temp': { weight: 2, very_early: true, early: true }
    };
    
    let totalScore = 0;
    let earlyCount = 0;
    let veryEarlyCount = 0;
    
    symptoms.forEach(symptom => {
        if (earlySymptoms[symptom]) {
            totalScore += earlySymptoms[symptom].weight;
            if (earlySymptoms[symptom].early) earlyCount++;
            if (earlySymptoms[symptom].very_early) veryEarlyCount++;
        }
    });
    
    // Calculate likelihood based on timing and symptoms
    let likelihood = 'low';
    let recommendation = '';
    
    if (daysPastOvulation === '7-10' && veryEarlyCount >= 2) {
        likelihood = 'moderate';
        recommendation = 'Very early signs present, but still too early for definitive testing';
    } else if (daysPastOvulation === '11-14' && earlyCount >= 3) {
        likelihood = 'high';
        recommendation = 'Strong early pregnancy indicators present';
    } else if (daysPastOvulation === '15-21' && earlyCount >= 4) {
        likelihood = 'very-high';
        recommendation = 'Very likely early pregnancy - consider testing';
    } else if (daysPastOvulation === '22+' && totalScore >= 5) {
        likelihood = 'very-high';
        recommendation = 'Pregnancy highly likely - confirm with test';
    } else if (totalScore >= 3 && daysPastOvulation !== '7-10') {
        likelihood = 'moderate';
        recommendation = 'Some early signs present - monitor and consider testing';
    }
    
    return {
        score: totalScore,
        likelihood: likelihood,
        recommendation: recommendation,
        symptoms: symptoms,
        daysPastOvulation: daysPastOvulation,
        nextSteps: getNextSteps(likelihood, daysPastOvulation)
    };
}

function getNextSteps(likelihood, daysPastOvulation) {
    const steps = [];
    
    if (likelihood === 'low') {
        steps.push('Monitor symptoms for a few more days');
        steps.push('Consider waiting until closer to expected period');
        steps.push('Track basal temperature if trying to conceive');
    } else if (likelihood === 'moderate') {
        steps.push('Wait 2-3 more days before testing');
        steps.push('Continue monitoring symptoms');
        steps.push('Consider early pregnancy test if period is due');
    } else if (likelihood === 'high') {
        steps.push('Take a home pregnancy test now');
        steps.push('Schedule confirmation with healthcare provider if positive');
        steps.push('Start prenatal vitamins if trying to conceive');
    } else if (likelihood === 'very-high') {
        steps.push('Test immediately with home pregnancy test');
        steps.push('Schedule doctor appointment for confirmation');
        steps.push('Begin prenatal care planning');
    }
    
    return steps;
}

