function calculateAdvancedBabyCosts() {
    // Get input elements
    const locationInput = document.getElementById('babyLocation');
    const incomeInput = document.getElementById('babyIncome');
    const childcareInput = document.getElementById('babyChildcare');
    const feedingInput = document.getElementById('babyFeeding');
    const insuranceInput = document.getElementById('babyInsurance');
    const babyCountInput = document.getElementById('babyCount');
    
    // Get values
    const location = locationInput?.value;
    const income = incomeInput?.value;
    const childcare = childcareInput?.value;
    const feeding = feedingInput?.value;
    const insurance = insuranceInput?.value;
    const babyCount = parseInt(babyCountInput?.value) || 1;
    
    if (!location || !income || !childcare || !feeding || !insurance) {
        showNotification('Please complete all fields to calculate baby costs', 'warning');
        return;
    }
    
    try {
        const costAnalysis = calculateAdvancedBabyCostAnalysis(location, income, childcare, feeding, insurance, babyCount);
        displayAdvancedBabyCostsResults(costAnalysis);
    } catch (error) {
        console.error('Error calculating baby costs:', error);
        showNotification('Error calculating baby costs. Please try again.', 'error');
    }
}

function calculateAdvancedBabyCostAnalysis(location, income, childcare, feeding, insurance, babyCount) {
    // Enhanced cost calculation with AI insights
    const baseCosts = {
        urban: { multiplier: 1.3, housing: 1500, childcare: 1200, food: 400 },
        suburban: { multiplier: 1.0, housing: 1200, childcare: 1000, food: 350 },
        rural: { multiplier: 0.8, housing: 900, childcare: 800, food: 300 }
    };
    
    const incomeMultipliers = {
        low: 0.7,
        middle: 1.0,
        high: 1.5,
        'very-high': 2.0
    };
    
    const childcareCosts = {
        'stay-home': { monthly: 0, notes: 'Parent provides full-time care' },
        'family': { monthly: 400, notes: 'Part-time family care arrangement' },
        'daycare': { monthly: baseCosts[location].childcare, notes: 'Full-time daycare center' },
        'nanny': { monthly: 2000, notes: 'Private nanny/babysitter' },
        'combination': { monthly: 1200, notes: 'Mixed childcare arrangements' }
    };
    
    const feedingCosts = {
        'breastfeeding': { monthly: 0, notes: 'Breastfeeding only' },
        'formula': { monthly: 150, notes: 'Formula feeding only' },
        'combination': { monthly: 75, notes: 'Mixed feeding methods' }
    };
    
    const insuranceSavings = {
        none: { monthly: 0, coverage: 0 },
        basic: { monthly: -200, coverage: 60 },
        good: { monthly: -400, coverage: 80 },
        excellent: { monthly: -600, coverage: 95 }
    };
    
    // Calculate costs with baby count multiplier
    const babyMultiplier = Math.min(babyCount, 2.5); // Diminishing returns for multiple children
    
    // Calculate monthly costs
    const baseMonthly = Math.round(300 * baseCosts[location].multiplier * babyMultiplier);
    const housingCost = Math.round(baseCosts[location].housing * babyMultiplier);
    const foodCost = Math.round(baseCosts[location].food * babyMultiplier);
    const childcareMonthly = childcareCosts[childcare].monthly * babyMultiplier;
    const feedingMonthly = feedingCosts[feeding].monthly * babyMultiplier;
    const insuranceMonthly = insuranceSavings[insurance].monthly;
    
    // One-time costs (multiplied by baby count)
    const oneTimeCosts = {
        nursery: Math.round(2000 * incomeMultipliers[income] * babyMultiplier),
        stroller: Math.round(500 * babyMultiplier),
        carSeat: Math.round(300 * babyMultiplier),
        crib: Math.round(400 * babyMultiplier),
        clothes: Math.round(800 * incomeMultipliers[income] * babyMultiplier),
        diapers: Math.round(100 * babyMultiplier)
    };
    
    // First year costs
    const totalOneTime = Object.values(oneTimeCosts).reduce((sum, cost) => sum + cost, 0);
    const monthlyTotal = baseMonthly + housingCost + foodCost + childcareMonthly + feedingMonthly + insuranceMonthly;
    const firstYearTotal = totalOneTime + (monthlyTotal * 12);
    
    return {
        location: location,
        income: income,
        childcare: childcare,
        feeding: feeding,
        insurance: insurance,
        babyCount: babyCount,
        monthly: {
            base: baseMonthly,
            housing: housingCost,
            food: foodCost,
            childcare: childcareMonthly,
            feeding: feedingMonthly,
            insurance: insuranceMonthly,
            total: monthlyTotal
        },
        oneTime: oneTimeCosts,
        total: {
            oneTime: totalOneTime,
            firstYear: firstYearTotal,
            averageMonthly: Math.round(firstYearTotal / 12),
            perChild: Math.round(firstYearTotal / babyCount)
        },
        savings: {
            monthly: insuranceSavings[insurance].monthly,
            annual: Math.abs(insuranceSavings[insurance].monthly * 12)
        },
        aiInsights: generateAICostInsights(location, income, childcare, babyCount),
        recommendations: generateAdvancedCostRecommendations(location, income, childcare, feeding, insurance, babyCount)
    };
}

function generateAICostInsights(location, income, childcare, babyCount) {
    const insights = [];
    
    // Location-based insights
    if (location === 'urban') {
        insights.push('Urban areas have higher childcare costs but more options');
        insights.push('Consider employer childcare benefits and flexible spending accounts');
    } else if (location === 'rural') {
        insights.push('Rural areas offer lower costs but limited childcare availability');
        insights.push('Family care arrangements can save 40-60% compared to daycare');
    }
    
    // Income-based insights
    if (income === 'very-high') {
        insights.push('High income enables premium childcare and educational investments');
        insights.push('Consider tax-advantaged 529 education savings plans');
    } else if (income === 'low') {
        insights.push('Focus on essential items and consider second-hand options');
        insights.push('Look for government assistance programs and community resources');
    }
    
    // Family size insights
    if (babyCount > 1) {
        insights.push(`Multiple children increase costs by ${Math.round((babyCount - 1) * 30)}% on average`);
        insights.push('Consider bulk purchases and hand-me-down strategies');
    }
    
    return insights;
}

function generateAdvancedCostRecommendations(location, income, childcare, feeding, insurance, babyCount) {
    const recommendations = [];
    
    // Location-based recommendations
    if (location === 'urban') {
        recommendations.push('Research employer-sponsored childcare benefits');
        recommendations.push('Consider flexible spending accounts for dependent care');
    } else if (location === 'rural') {
        recommendations.push('Explore family care co-ops and community childcare networks');
        recommendations.push('Consider carpooling and shared transportation solutions');
    }
    
    // Income-based recommendations
    if (income === 'very-high') {
        recommendations.push('Set up automated investment plans for college education');
        recommendations.push('Consider high-yield savings accounts and investment portfolios');
    } else if (income === 'low') {
        recommendations.push('Apply for WIC, SNAP, and other government assistance programs');
        recommendations.push('Look into local diaper banks and community resource centers');
    }
    
    // Childcare recommendations
    if (childcare === 'daycare') {
        recommendations.push('Ask about sibling discounts and employer childcare subsidies');
        recommendations.push('Consider flexible schedules to reduce part-time care needs');
    } else if (childcare === 'nanny') {
        recommendations.push('Verify nanny credentials and background checks');
        recommendations.push('Consider nanny-share arrangements for cost sharing');
    }
    
    // Feeding recommendations
    if (feeding === 'formula') {
        recommendations.push('Buy formula in bulk and subscribe to delivery services');
        recommendations.push('Compare store brands vs name brands for cost savings');
    } else if (feeding === 'breastfeeding') {
        recommendations.push('Invest in quality breast pump and storage solutions');
        recommendations.push('Check insurance coverage for breast pump supplies');
    }
    
    // Multi-child recommendations
    if (babyCount > 1) {
        recommendations.push('Invest in durable items that can be reused');
        recommendations.push('Create shared spaces and hand-me-down systems');
    }
    
    return recommendations;
}

