function calculateBabyCosts() {
    const location = document.getElementById('babyLocation')?.value;
    const income = document.getElementById('babyIncome')?.value;
    const childcare = document.getElementById('babyChildcare')?.value;
    const feeding = document.getElementById('babyFeeding')?.value;
    const insurance = document.getElementById('babyInsurance')?.value;
    
    if (!location || !income || !childcare || !feeding || !insurance) {
        showNotification('Please complete all fields to calculate baby costs', 'warning');
        return;
    }
    
    try {
        const costAnalysis = calculateBabyCostAnalysis(location, income, childcare, feeding, insurance);
        displayBabyCostsResults(costAnalysis);
    } catch (error) {
        console.error('Error calculating baby costs:', error);
        showNotification('Error calculating baby costs. Please try again.', 'error');
    }
}

function calculateBabyCostAnalysis(location, income, childcare, feeding, insurance) {
    // Validate inputs
    if (!baseCosts[location] || !incomeMultipliers[income] || !childcareCosts[childcare] || !feedingCosts[feeding] || !insuranceSavings[insurance]) {
        throw new Error('Invalid input values for cost calculation');
    }
    
    // Base costs by category
    const baseCosts = {
        urban: { multiplier: 1.3, housing: 1500, childcare: 1200 },
        suburban: { multiplier: 1.0, housing: 1200, childcare: 1000 },
        rural: { multiplier: 0.8, housing: 900, childcare: 800 }
    };
    
    const incomeMultipliers = {
        low: 0.7,
        middle: 1.0,
        high: 1.5,
        'very-high': 2.0
    };
    
    const childcareCosts = {
        'stay-home': { monthly: 0, notes: 'Parent provides full-time care' },
        'family': { monthly: 400, notes: 'Part-time family care arrangement' },
        'daycare': { monthly: baseCosts[location].childcare, notes: 'Full-time daycare center' },
        'nanny': { monthly: 2000, notes: 'Private nanny/babysitter' },
        'combination': { monthly: 1200, notes: 'Mixed childcare arrangements' }
    };
    
    const feedingCosts = {
        'breastfeeding': { monthly: 0, notes: 'Breastfeeding only' },
        'formula': { monthly: 150, notes: 'Formula feeding only' },
        'combination': { monthly: 75, notes: 'Mixed feeding methods' }
    };
    
    const insuranceSavings = {
        none: { monthly: 0, coverage: 0 },
        basic: { monthly: -200, coverage: 60 },
        good: { monthly: -400, coverage: 80 },
        excellent: { monthly: -600, coverage: 95 }
    };
    
    // Calculate monthly costs
    const baseMonthly = Math.round(800 * baseCosts[location].multiplier); // Base baby supplies
    const housingCost = baseCosts[location].housing;
    const childcareMonthly = childcareCosts[childcare].monthly;
    const feedingMonthly = feedingCosts[feeding].monthly;
    const insuranceMonthly = insuranceSavings[insurance].monthly;
    
    // One-time costs
    const oneTimeCosts = {
        nursery: Math.round(2000 * incomeMultipliers[income]),
        stroller: 500,
        carSeat: 300,
        crib: 400,
        clothes: Math.round(800 * incomeMultipliers[income]),
        diapers: 100
    };
    
    // First year costs
    const totalOneTime = Object.values(oneTimeCosts).reduce((sum, cost) => sum + cost, 0);
    const monthlyTotal = baseMonthly + housingCost + childcareMonthly + feedingMonthly + insuranceMonthly;
    const firstYearTotal = totalOneTime + (monthlyTotal * 12);
    
    return {
        location: location,
        income: income,
        childcare: childcare,
        feeding: feeding,
        insurance: insurance,
        monthly: {
            base: baseMonthly,
            housing: housingCost,
            childcare: childcareMonthly,
            feeding: feedingMonthly,
            insurance: insuranceMonthly,
            total: monthlyTotal
        },
        oneTime: oneTimeCosts,
        total: {
            oneTime: totalOneTime,
            firstYear: firstYearTotal,
            averageMonthly: Math.round(firstYearTotal / 12)
        },
        savings: {
            monthly: insuranceSavings[insurance].monthly,
            annual: Math.abs(insuranceSavings[insurance].monthly * 12)
        },
        recommendations: generateCostRecommendations(location, income, childcare, feeding, insurance)
    };
}

function generateCostRecommendations(location, income, childcare, feeding, insurance) {
    const recommendations = [];
    
    // Location-based recommendations
    if (location === 'urban') {
        recommendations.push('Consider moving to suburban areas for lower childcare costs');
        recommendations.push('Look for government childcare subsidies in urban areas');
    }
    
    // Income-based recommendations
    if (income === 'low') {
        recommendations.push('Apply for WIC and other government assistance programs');
        recommendations.push('Consider second-hand baby items and clothing exchanges');
        recommendations.push('Look for community parenting groups for shared resources');
    } else if (income === 'middle') {
        recommendations.push('Create a detailed monthly budget with emergency fund');
        recommendations.push('Compare childcare providers for best value');
    } else if (income === 'high' || income === 'very-high') {
        recommendations.push('Consider high-quality childcare with educational benefits');
        recommendations.push('Invest in premium baby gear for longevity');
    }
    
    // Childcare recommendations
    if (childcare === 'stay-home') {
        recommendations.push('Parent should consider part-time work options if needed');
        recommendations.push('Look into parent support groups for socialization');
    } else if (childcare === 'daycare') {
        recommendations.push('Visit multiple daycare centers before committing');
        recommendations.push('Ask about sibling discounts and flexible scheduling');
    }
    
    // Feeding recommendations
    if (feeding === 'formula') {
        recommendations.push('Buy formula in bulk for cost savings');
        recommendations.push('Consider store brands vs name brands');
    } else if (feeding === 'breastfeeding') {
        recommendations.push('Invest in quality breast pump for flexibility');
        recommendations.push('Check insurance coverage for breast pump supplies');
    }
    
    // Insurance recommendations
    if (insurance === 'none' || insurance === 'basic') {
        recommendations.push('Research marketplace insurance options');
        recommendations.push('Consider employer-sponsored plans if available');
    }
    
    return recommendations;
}

