function renderBabyRealtimeStream() {
    const profile = getStoredBabyProfile();
    const ageDays = profile?.ageInDays || 184;
    const temp = (36.5 + (ageDays % 5) * 0.08).toFixed(1);
    const sleep = ageDays < 90 ? '15.5 hrs' : ageDays < 180 ? '14.0 hrs' : '12.8 hrs';
    const feeds = ageDays < 180 ? '7 feeds' : '5 feeds';
    const mood = ageDays % 3 === 0 ? 'Curious' : ageDays % 2 === 0 ? 'Calm' : 'Happy';
    const updates = [
        ['realtime-temp', `${temp} C`],
        ['realtime-temp-time', 'Updated now'],
        ['realtime-sleep', sleep],
        ['realtime-sleep-time', 'Synced from care model'],
        ['realtime-feeding', feeds],
        ['realtime-feeding-time', 'Predicted today'],
        ['realtime-mood', mood],
        ['realtime-mood-time', 'Pattern estimate']
    ];
    updates.forEach(([id, value]) => {
        const el = document.getElementById(id);
        if (el) el.textContent = value;
    });
}

function openBabyAdvancedTool(toolKey) {
    const tool = babyAdvancedTools[toolKey] || babyAdvancedTools.growth;
    const profile = getStoredBabyProfile();
    const babyName = profile?.name || 'Baby';
    const modal = document.createElement('div');
    modal.className = 'baby-pro-modal';
    modal.innerHTML = `
        <div class="baby-pro-dialog">
            <div class="baby-pro-dialog-head" style="background: linear-gradient(135deg, ${tool.accent}, #0f172a);">
                <div>
                    <span>Advanced Baby Tool</span>
                    <h2>${tool.title}</h2>
                    <p>${tool.body}</p>
                </div>
                <button type="button" onclick="this.closest('.baby-pro-modal').remove()">Close</button>
            </div>
            <div class="baby-pro-dialog-body">
                <div class="baby-pro-metrics">
                    ${tool.stats.map(([label, value]) => `<div><strong>${value}</strong><span>${label}</span></div>`).join('')}
                    <div><strong>${babyName}</strong><span>Profile</span></div>
                </div>
                <div class="baby-pro-result">
                    <h3>Smart Result</h3>
                    <ul>${tool.result.map(item => `<li>${item}</li>`).join('')}</ul>
                </div>
                <div class="baby-pro-actions">
                    <button type="button" onclick="saveBabyToolResult('${toolKey}')">Save Result</button>
                    <button type="button" onclick="downloadBabyToolResult('${toolKey}')">Download</button>
                </div>
            </div>
        </div>
    `;
    document.body.appendChild(modal);
}

function saveBabyToolResult(toolKey) {
    const tool = babyAdvancedTools[toolKey] || babyAdvancedTools.growth;
    const record = { tool: tool.title, result: tool.result, date: new Date().toISOString() };
    const saved = JSON.parse(localStorage.getItem('mamasafe_baby_tool_results') || '[]');
    saved.unshift(record);
    localStorage.setItem('mamasafe_baby_tool_results', JSON.stringify(saved.slice(0, 30)));
    if (window.DB_SYNC) window.DB_SYNC.saveBaby({ type: 'tool-result', ...record });
    showNotification(`${tool.title} result saved.`, 'success');
}

function downloadBabyToolResult(toolKey) {
    const tool = babyAdvancedTools[toolKey] || babyAdvancedTools.growth;
    const text = `${tool.title}\n\n${tool.body}\n\nResults:\n- ${tool.result.join('\n- ')}\n\nGenerated by Mamasafe`;
    const blob = new Blob([text], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${tool.title.toLowerCase().replace(/[^a-z0-9]+/g, '-')}.txt`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
}

const babyCareStages = {
    12: { label: '12-18 month', sleep: '11-14h', meals: '3+2', skills: 5, advice: 'Focus on safe walking, first words, simple routines, finger foods, and calm separation practice.' },
    19: { label: '19-24 month', sleep: '11-13h', meals: '3+2', skills: 6, advice: 'Support independence with choices, consistent boundaries, language repetition, and one predictable nap.' },
    25: { label: '25-30 month', sleep: '10-13h', meals: '3+2', skills: 7, advice: 'Build potty readiness, pretend play, two-step instructions, safe climbing, and picky-eating patience.' },
    31: { label: '31-36 month', sleep: '10-13h', meals: '3+2', skills: 8, advice: 'Prepare preschool skills: turn-taking, storytelling, dressing practice, safety rules, and emotional naming.' }
};

function getBabyCareAge() {
    return Math.min(36, Math.max(12, parseInt(document.getElementById('babyCareAge')?.value || localStorage.getItem('baby_care_age') || '18', 10) || 18));
}

function getBabyCareStage(age = getBabyCareAge()) {
    if (age <= 18) return babyCareStages[12];
    if (age <= 24) return babyCareStages[19];
    if (age <= 30) return babyCareStages[25];
    return babyCareStages[31];
}

function initializeBabyCarePage() {
    babyCareSelectStage(getBabyCareAge(), false);
}

function babyCareSelectStage(age, updateInput = true) {
    const stage = getBabyCareStage(age);
    localStorage.setItem('baby_care_age', String(age));
    if (updateInput && document.getElementById('babyCareAge')) document.getElementById('babyCareAge').value = age;
    document.querySelectorAll('#babyStageStrip button').forEach(btn => {
        const btnAge = parseInt(btn.dataset.age || '0', 10);
        btn.classList.toggle('active', getBabyCareStage(btnAge).label === stage.label);
    });
    const title = document.getElementById('babyCareSummaryTitle');
    const sleep = document.getElementById('babyCareSleepMetric');
    const meals = document.getElementById('babyCareMealsMetric');
    const skills = document.getElementById('babyCareMilestoneMetric');
    const advice = document.getElementById('babyCareStageAdvice');
    if (title) title.textContent = `${stage.label} care snapshot`;
    if (sleep) sleep.textContent = stage.sleep;
    if (meals) meals.textContent = stage.meals;
    if (skills) skills.textContent = stage.skills;
    if (advice) advice.innerHTML = `<strong>Stage focus:</strong> ${stage.advice}`;
}

function babyCareSetPanel(panel) {
    document.querySelectorAll('.baby-care-panel').forEach(el => el.classList.remove('active'));
    document.querySelectorAll('[data-baby-panel]').forEach(el => el.classList.remove('active'));
    document.getElementById(`baby-care-${panel}-panel`)?.classList.add('active');
    document.querySelector(`[data-baby-panel="${panel}"]`)?.classList.add('active');
}

function babyCareSaveProfile(event) {
    event.preventDefault();
    const profile = {
        name: document.getElementById('babyCareName')?.value.trim() || 'Your child',
        age: getBabyCareAge(),
        focus: document.getElementById('babyCareFocus')?.value || 'routine',
        updatedAt: new Date().toISOString()
    };
    localStorage.setItem('baby_care_profile', JSON.stringify(profile));
    if (window.DB_SYNC) window.DB_SYNC.saveBaby({ type: 'care-profile', ...profile });
    babyCareSelectStage(profile.age, false);
    const result = document.getElementById('babyCareProfileResult');
    if (result) result.innerHTML = `<strong>${profile.name}</strong> is set for ${getBabyCareStage(profile.age).label} guidance. Focus: ${profile.focus.replace('-', ' ')}.`;
    showNotification('Baby care profile saved.', 'success');
}

function babyCareGenerateRoutine(mode) {
    const stage = getBabyCareStage();
    const plans = {
        balanced: ['7:00 wake + breakfast', '9:30 outdoor or active play', '12:00 lunch', '13:00 nap or quiet time', '15:30 snack + learning play', '18:00 dinner', '19:30 bath, books, bed'],
        busy: ['Morning: breakfast + 15 min focused play', 'Midday: lunch + nap/quiet time', 'Afternoon: snack + safe independent play', 'Evening: simple dinner + bath + books'],
        sick: ['Offer fluids often', 'Keep meals small and gentle', 'Prioritize rest and comfort', 'Monitor temperature and wet diapers', 'Call care provider for red flags']
    };
    const result = document.getElementById('babyCareRoutineResult');
    if (result) result.innerHTML = `<strong>${stage.label} ${mode} plan</strong><ul>${plans[mode].map(item => `<li>${item}</li>`).join('')}</ul>`;
}

function babyCareAnalyzeGrowth() {
    const age = getBabyCareAge();
    const weight = parseFloat(document.getElementById('babyCareWeight')?.value);
    const height = parseFloat(document.getElementById('babyCareHeight')?.value);
    const head = parseFloat(document.getElementById('babyCareHead')?.value);
    const result = document.getElementById('babyCareGrowthResult');
    if (Number.isNaN(weight) || Number.isNaN(height)) {
        showNotification('Enter weight and height to analyze growth.', 'error');
        return;
    }
    const expectedWeight = 8.8 + age * 0.18;
    const expectedHeight = 72 + age * 0.75;
    const weightStatus = weight < expectedWeight - 2 ? 'lower than expected' : weight > expectedWeight + 3 ? 'higher than expected' : 'in the expected range';
    const heightStatus = height < expectedHeight - 5 ? 'lower than expected' : height > expectedHeight + 5 ? 'higher than expected' : 'in the expected range';
    if (result) result.innerHTML = `<strong>Growth review:</strong> Weight is ${weightStatus}; height is ${heightStatus}. ${Number.isNaN(head) ? 'Add head circumference if you have it.' : `Head circumference recorded: ${head} cm.`} Keep trend records and review unusual changes with a pediatrician.`;
}

function babyCareBuildNutritionPlan() {
    const eating = document.getElementById('babyCareEating')?.value;
    const allergy = document.getElementById('babyCareAllergy')?.value.trim() || 'none';
    const milk = document.getElementById('babyCareMilk')?.value;
    const result = document.getElementById('babyCareNutritionResult');
    const picky = eating === 'picky' ? '<li>Serve tiny portions with one safe food and one learning food.</li>' : '<li>Offer family foods in soft, safe pieces.</li>';
    const milkTip = milk === 'high' ? '<li>High milk can reduce appetite for iron-rich foods; balance with meals.</li>' : '<li>Keep water available and milk intake steady.</li>';
    if (result) result.innerHTML = `<strong>Meal rhythm:</strong><ul><li>3 meals and 2 snacks.</li>${picky}<li>Include iron, protein, fruit/vegetable, and healthy fat daily.</li>${milkTip}<li>Allergy note: ${allergy}. Introduce new foods one at a time if concerned.</li></ul>`;
}

function babyCareAnalyzeSleep() {
    const wake = document.getElementById('babyCareWake')?.value || '07:00';
    const nap = document.getElementById('babyCareNap')?.value;
    const issue = document.getElementById('babyCareSleepIssue')?.value;
    const result = document.getElementById('babyCareSleepResult');
    const napText = nap === 'two' ? 'two shorter naps, then shift toward one nap when ready' : nap === 'none' ? 'quiet rest time after lunch' : 'one midday nap';
    const issueTip = issue === 'waking' ? 'Check bedtime timing, hunger, teething, and room comfort.' : issue === 'bedtime' ? 'Use the same 20 minute wind-down routine nightly.' : issue === 'early' ? 'Try a darker room and avoid too-early bedtime.' : 'Keep the routine steady.';
    if (result) result.innerHTML = `<strong>Sleep plan:</strong> Wake around ${wake}. Use ${napText}. Target ${getBabyCareStage().sleep} total sleep. ${issueTip}`;
}

function babyCareAssessDevelopment() {
    const checked = document.querySelectorAll('.baby-dev-check:checked').length;
    const total = document.querySelectorAll('.baby-dev-check').length;
    const pct = Math.round((checked / total) * 100);
    const msg = pct >= 75 ? 'Many expected skills are present. Keep offering language, movement, and social play.' : pct >= 45 ? 'Some skills are emerging. Repeat simple games daily and watch progress.' : 'Consider discussing development concerns with a pediatric provider.';
    const result = document.getElementById('babyCareDevelopmentResult');
    if (result) result.innerHTML = `<strong>${checked}/${total} skills observed (${pct}%).</strong> ${msg}`;
}

function babyCarePlanVaccines() {
    const date = document.getElementById('babyCareVaccineDate')?.value;
    const type = document.getElementById('babyCareAppointment')?.value;
    const result = document.getElementById('babyCareVaccineResult');
    if (result) result.innerHTML = `<strong>Visit plan:</strong> ${type.replace('-', ' ')} visit selected. ${date ? `Last vaccine date: ${new Date(date).toLocaleDateString()}.` : 'Add the last vaccine date if known.'} Bring the child health card, questions, medication list, and growth notes.`;
}

function babyCareRunSafetyScan() {
    const done = document.querySelectorAll('.baby-safety-check:checked').length;
    const total = document.querySelectorAll('.baby-safety-check').length;
    const result = document.getElementById('babyCareSafetyResult');
    if (result) result.innerHTML = `<strong>Safety score: ${done}/${total}.</strong> ${done === total ? 'Great coverage. Review weekly as mobility changes.' : 'Finish unchecked items first, especially medicines, choking hazards, water safety, and emergency contacts.'}`;
}

function babyCareCheckHealth() {
    const temp = parseFloat(document.getElementById('babyCareTemp')?.value);
    const symptom = document.getElementById('babyCareSymptom')?.value;
    const hydration = document.getElementById('babyCareHydration')?.value;
    const urgent = temp >= 39 || symptom === 'breathing' || symptom === 'lethargy' || hydration === 'very-low';
    const result = document.getElementById('babyCareHealthResult');
    if (result) result.innerHTML = urgent
        ? '<strong>Urgent guidance:</strong> Contact emergency care or a healthcare professional now, especially for breathing trouble, unusual sleepiness, high fever, or very low wet diapers.'
        : '<strong>Home monitoring:</strong> Keep fluids available, monitor temperature and wet diapers, and contact a clinician if symptoms worsen, persist, or worry you.';
}

