function createSmartBabyProfile() {
    // Get form values
    const babyName = document.getElementById('smartBabyName')?.value;
    const birthDateTime = document.getElementById('smartBabyBirthDateTime')?.value;
    const weight = parseFloat(document.getElementById('smartBabyWeight')?.value);
    const length = parseFloat(document.getElementById('smartBabyLength')?.value);
    const feedingMethod = document.getElementById('smartFeedingMethod')?.value;
    
    // Validate inputs
    if (!babyName || !birthDateTime || !weight || !length || !feedingMethod) {
        showNotification('Please fill in all baby profile fields', 'error');
        return;
    }
    
    // Calculate baby's current age
    const birthDate = new Date(birthDateTime);
    const today = new Date();
    const ageInDays = Math.floor((today - birthDate) / (1000 * 60 * 60 * 24));
    const ageInWeeks = Math.floor(ageInDays / 7);
    const ageInMonths = Math.floor(ageInDays / 30);
    
    // Generate AI-powered insights
    const aiInsights = generateBabyAIInsights(ageInDays, weight, length, feedingMethod);
    
    // Display results
    const resultDiv = document.getElementById('smartProfileResult');
    if (resultDiv) {
        resultDiv.innerHTML = `
            <div class="smart-profile-result" style="background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 30px; border-radius: 20px;">
                <div style="text-align: center; margin-bottom: 25px;">
                    <h3 style="font-size: 28px; margin-bottom: 10px;">AI Baby Profile Created!</h3>
                    <p style="font-size: 18px; opacity: 0.9;">Personalized insights for ${babyName}</p>
                </div>
                
                <div class="profile-stats" style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 20px; margin-bottom: 30px;">
                    <div style="background: rgba(255,255,255,0.2); padding: 20px; border-radius: 15px; text-align: center;">
                        <div style="font-size: 24px; font-weight: bold; margin-bottom: 5px;">${ageInDays}</div>
                        <div style="font-size: 14px; opacity: 0.9;">Days Old</div>
                    </div>
                    <div style="background: rgba(255,255,255,0.2); padding: 20px; border-radius: 15px; text-align: center;">
                        <div style="font-size: 24px; font-weight: bold; margin-bottom: 5px;">${weight} kg</div>
                        <div style="font-size: 14px; opacity: 0.9;">Current Weight</div>
                    </div>
                    <div style="background: rgba(255,255,255,0.2); padding: 20px; border-radius: 15px; text-align: center;">
                        <div style="font-size: 24px; font-weight: bold; margin-bottom: 5px;">${length} cm</div>
                        <div style="font-size: 14px; opacity: 0.9;">Current Length</div>
                    </div>
                </div>
                
                <div class="ai-insights" style="background: rgba(255,255,255,0.1); padding: 25px; border-radius: 15px; margin-bottom: 20px;">
                    <h4 style="margin-bottom: 15px; font-size: 20px;">AI-Powered Insights</h4>
                    <ul style="list-style: none; padding: 0; margin: 0;">
                        ${aiInsights.map(insight => `<li style="padding: 8px 0; border-bottom: 1px solid rgba(255,255,255,0.2);">• ${insight}</li>`).join('')}
                    </ul>
                </div>
                
                <div class="recommendations" style="background: rgba(255,255,255,0.1); padding: 25px; border-radius: 15px; margin-bottom: 20px;">
                    <h4 style="margin-bottom: 15px; font-size: 20px;">Personalized Recommendations</h4>
                    <div style="display: grid; gap: 15px;">
                        ${generateBabyRecommendations(ageInDays, feedingMethod).map(rec => `
                            <div style="background: rgba(255,255,255,0.2); padding: 15px; border-radius: 10px;">
                                <strong>${rec.title}</strong>
                                <p style="margin: 5px 0 0 0; font-size: 14px; opacity: 0.9;">${rec.description}</p>
                            </div>
                        `).join('')}
                    </div>
                </div>
                
                <div style="text-align: center; margin-top: 25px;">
                    <button onclick="downloadBabyProfile()" style="background: white; color: #667eea; padding: 12px 24px; border: none; border-radius: 8px; font-weight: 600; cursor: pointer; margin-right: 10px;">
                        Download Profile
                    </button>
                    <button onclick="shareBabyProfile()" style="background: rgba(255,255,255,0.2); color: white; padding: 12px 24px; border: 1px solid rgba(255,255,255,0.3); border-radius: 8px; font-weight: 600; cursor: pointer;">
                        Share Profile
                    </button>
                </div>
            </div>
        `;
        
        resultDiv.style.display = 'block';
        resultDiv.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
    
    // Store baby data for other functions
    window.babyProfileData = {
        name: babyName,
        birthDate: birthDate,
        weight: weight,
        length: length,
        feedingMethod: feedingMethod,
        ageInDays: ageInDays,
        ageInWeeks: ageInWeeks,
        ageInMonths: ageInMonths
    };
    
    showNotification(`Smart AI profile created for ${babyName}!`, 'success');
}

// Enhanced AI-powered insights for baby
function generateBabyAIInsights(ageInDays, weight, length, feedingMethod) {
    const insights = [];
    const ageInMonths = Math.floor(ageInDays / 30);
    
    // Advanced AI growth analysis
    const growthPercentile = calculateAIGrowthPercentile(weight, length, ageInDays);
    insights.push(`📊 AI Growth Analysis: ${growthPercentile}%ile for weight and length`);
    
    // Developmental predictions
    const developmentalAge = calculateAIDevelopmentalAge(ageInDays, weight, length);
    insights.push(`🧠 AI Developmental Age: ${developmentalAge.months} months (adjusted for growth pattern)`);
    
    // Health monitoring insights
    const healthStatus = analyzeBabyHealth(weight, length, ageInDays);
    insights.push(`🏥 AI Health Status: ${healthStatus.overall} - ${healthStatus.recommendations[0]}`);
    
    // Feeding optimization
    const feedingInsights = optimizeFeedingSchedule(feedingMethod, ageInDays);
    insights.push(`🍼 AI Feeding Optimization: ${feedingInsights.schedule}`);
    
    // Sleep pattern analysis
    const sleepAnalysis = analyzeBabySleepPatterns(ageInDays);
    insights.push(`😴 AI Sleep Analysis: ${sleepAnalysis.pattern}`);
    
    // Milestone tracking
    const milestonePrediction = predictNextMilestones(ageInDays);
    insights.push(`🎯 AI Milestone Prediction: ${milestonePrediction.nextMilestone} expected around ${milestonePrediction.timeframe}`);
    
    // Growth insights
    insights.push("💡 AI Tip: Track head circumference for brain development monitoring");
    insights.push("🧘 AI Tip: Monitor for developmental red flags like lack of eye contact");
    insights.push("📈 AI Tip: Consistent routine helps with developmental tracking");
    
    return insights;
}

// Calculate AI growth percentile
function calculateAIGrowthPercentile(weight, length, ageInDays) {
    // Simplified percentile calculation (in real app, would use WHO growth charts)
    const weightScore = Math.min(Math.max((weight / (ageInDays * 0.03)) * 100, 150), 100);
    const lengthScore = Math.min(Math.max((length / (ageInDays * 0.15)) * 100, 150), 100);
    return Math.round((weightScore + lengthScore) / 2);
}

// Calculate AI developmental age
function calculateAIDevelopmentalAge(ageInDays, weight, length) {
    const ageInMonths = Math.floor(ageInDays / 30);
    let adjustment = 0;
    
    if (weight > ageInDays * 0.025) adjustment += 0.5; // Above average weight
    if (length > ageInDays * 0.5) adjustment += 0.3; // Above average length
    
    const adjustedAge = ageInMonths + adjustment;
    return {
        months: Math.round(adjustedAge),
        adjustment: adjustment
    };
}

// Analyze baby health with AI
function analyzeBabyHealth(weight, length, ageInDays) {
    const bmi = weight / Math.pow(length / 100, 2);
    let status = 'Excellent';
    const recommendations = [];
    
    if (bmi < 14) {
        status = 'Underweight';
        recommendations.push('Consult pediatrician about feeding schedule');
    } else if (bmi > 20) {
        status = 'Overweight';
        recommendations.push('Monitor feeding amounts and growth pattern');
    } else {
        recommendations.push('Continue current feeding and care routine');
    }
    
    return {
        overall: status,
        recommendations: recommendations
    };
}

// Optimize feeding schedule with AI
function optimizeFeedingSchedule(method, ageInDays) {
    const schedules = {
        'breastfeeding': 'Every 2-3 hours during day, on-demand at night',
        'formula': 'Every 3-4 hours, 4-6 oz per feeding',
        'mixed': 'Alternate breastmilk and formula, watch for hunger cues'
    };
    
    return {
        schedule: schedules[method] || 'Every 3-4 hours',
        nextFeeding: 'Watch for rooting, hand-to-mouth, and sucking cues'
    };
}

// Analyze baby sleep patterns with AI
function analyzeBabySleepPatterns(ageInDays) {
    const patterns = {
        '0-3': 'Newborn pattern: 16-18 hours total, 2-4 hour naps',
        '3-6': 'Infant pattern: 14-16 hours total, 3 naps',
        '6-12': 'Baby pattern: 12-14 hours total, 2 naps'
    };
    
    const ageRange = ageInDays <= 90 ? '0-3' : ageInDays <= 180 ? '3-6' : '6-12';
    
    return {
        pattern: patterns[ageRange],
        recommendation: 'Establish consistent bedtime routine and watch for sleep cues'
    };
}

// Predict next developmental milestones with AI
function predictNextMilestones(ageInDays) {
    const milestones = {
        '0-90': ['Social smile', 'Tracking objects', 'Holding head steady'],
        '90-180': ['Rolling over', 'Sitting with support', 'Babbling'],
        '180-270': ['Crawling', 'Pulling to stand', 'First words'],
        '270-365': ['Walking independently', 'Simple sentences', 'Using utensils']
    };
    
    const ageRange = ageInDays <= 90 ? '0-90' : ageInDays <= 180 ? '90-180' : '180-365';
    const currentMilestones = milestones[ageRange] || [];
    const nextMilestone = currentMilestones[0] || 'Continued development';
    const timeframe = ageInDays <= 90 ? 'next 1-2 months' : ageInDays <= 180 ? 'next 2-3 months' : 'next 3-4 months';
    
    return {
        nextMilestone,
        timeframe
    };
}

// Generate personalized recommendations
function generateBabyRecommendations(ageInDays, feedingMethod) {
    const recommendations = [];
    
    // Age-based recommendations
    if (ageInDays < 30) {
        recommendations.push({
            title: 'Newborn Care',
            description: 'Feed every 2-3 hours, ensure 16-18 hours of sleep, monitor temperature regularly'
        });
    } else if (ageInDays < 90) {
        recommendations.push({
            title: 'Infant Development',
            description: 'Establish daily routines, introduce tummy time, track developmental milestones'
        });
    } else {
        recommendations.push({
            title: 'Advanced Care',
            description: 'Encourage exploration, introduce solid foods, monitor motor skill development'
        });
    }
    
    // Feeding recommendations
    if (feedingMethod === 'breastfeeding') {
        recommendations.push({
            title: 'Breastfeeding Tips',
            description: 'Ensure proper latch, stay hydrated, monitor milk supply, consider vitamin D supplements'
        });
    } else if (feedingMethod === 'formula') {
        recommendations.push({
            title: 'Formula Feeding',
            description: 'Prepare formula correctly, maintain hygiene, watch for allergies, establish feeding schedule'
        });
    } else {
        recommendations.push({
            title: 'Mixed Feeding',
            description: 'Balance breast milk and formula, monitor baby\'s preference, maintain consistent routine'
        });
    }
    
    // General recommendations
    recommendations.push({
        title: 'Health Monitoring',
        description: 'Regular pediatric check-ups, track growth metrics, monitor developmental milestones, maintain vaccination schedule'
    });
    
    return recommendations;
}

// Download baby profile
function downloadBabyProfile() {
    if (!window.babyProfileData) {
        showNotification('No baby profile data available', 'error');
        return;
    }
    
    const profileData = window.babyProfileData;
    const content = `
BABY AI PROFILE REPORT
====================

Baby Information:
- Name: ${profileData.name}
- Birth Date: ${profileData.birthDate.toLocaleDateString()}
- Current Age: ${profileData.ageInDays} days (${profileData.ageInWeeks} weeks, ${profileData.ageInMonths} months)
- Weight: ${profileData.weight} kg
- Length: ${profileData.length} cm
- Feeding Method: ${profileData.feedingMethod}

AI Insights:
${generateBabyAIInsights(profileData.ageInDays, profileData.weight, profileData.length, profileData.feedingMethod).join('\n')}

Recommendations:
${generateBabyRecommendations(profileData.ageInDays, profileData.feedingMethod).map(rec => `- ${rec.title}: ${rec.description}`).join('\n')}

Generated: ${new Date().toLocaleString()}
By Mamasafe assistant AI
    `;
    
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `baby-profile-${profileData.name}.txt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    
    showNotification('Baby profile downloaded successfully!', 'success');
}

// Share baby profile
function shareBabyProfile() {
    if (!window.babyProfileData) {
        showNotification('No baby profile data available', 'error');
        return;
    }
    
    const profileData = window.babyProfileData;
    const shareText = `Check out ${profileData.name}'s AI-powered baby profile! Age: ${profileData.ageInDays} days, Weight: ${profileData.weight} kg`;
    
    if (navigator.share) {
        navigator.share({
            title: `${profileData.name}'s AI Baby Profile`,
            text: shareText,
            url: window.location.href
        }).then(() => {
            showNotification('Profile shared successfully!', 'success');
        }).catch(() => {
            navigator.clipboard.writeText(shareText);
            showNotification('Profile copied to clipboard!', 'success');
        });
    } else {
        navigator.clipboard.writeText(shareText);
        showNotification('Profile copied to clipboard!', 'success');
    }
}

