function generateVaccineSchedule() {
    const birthDate = document.getElementById('vaccineBabyBirthDate')?.value;
    
    if (!birthDate) {
        alert('Please enter your baby\'s birth date');
        return;
    }
    
    const birth = new Date(birthDate);
    const today = new Date();
    const ageInMonths = Math.floor((today - birth) / (30 * 24 * 60 * 60 * 1000));
    
    // Enhanced vaccine schedule with more comprehensive timeline
    const schedule = [
        { age: 'Birth', vaccines: 'Hepatitis B (1st dose)', date: birth, status: getVaccineStatus(birth, today) },
        { age: '1-2 Months', vaccines: 'Hepatitis B (2nd dose)', date: new Date(birth.getTime() + 30 * 24 * 60 * 60 * 1000), status: getVaccineStatus(new Date(birth.getTime() + 30 * 24 * 60 * 60 * 1000), today) },
        { age: '2 Months', vaccines: 'DTaP, Hib, IPV, PCV, Rotavirus (1st dose)', date: new Date(birth.getTime() + 60 * 24 * 60 * 60 * 1000), status: getVaccineStatus(new Date(birth.getTime() + 60 * 24 * 60 * 60 * 1000), today) },
        { age: '4 Months', vaccines: 'DTaP, Hib, IPV, PCV, Rotavirus (2nd dose)', date: new Date(birth.getTime() + 120 * 24 * 60 * 60 * 1000), status: getVaccineStatus(new Date(birth.getTime() + 120 * 24 * 60 * 60 * 1000), today) },
        { age: '6 Months', vaccines: 'DTaP, Hib, IPV, PCV, Rotavirus (3rd dose), Flu (yearly)', date: new Date(birth.getTime() + 180 * 24 * 60 * 60 * 1000), status: getVaccineStatus(new Date(birth.getTime() + 180 * 24 * 60 * 60 * 1000), today) },
        { age: '12-15 Months', vaccines: 'Hib, PCV, MMR, Varicella (1st dose)', date: new Date(birth.getTime() + 365 * 24 * 60 * 60 * 1000), status: getVaccineStatus(new Date(birth.getTime() + 365 * 24 * 60 * 60 * 1000), today) },
        { age: '18 Months', vaccines: 'DTaP (4th dose), Hepatitis A (2nd dose)', date: new Date(birth.getTime() + 540 * 24 * 60 * 60 * 1000), status: getVaccineStatus(new Date(birth.getTime() + 540 * 24 * 60 * 60 * 1000), today) },
        { age: '4-6 Years', vaccines: 'DTaP (5th dose), MMR (2nd dose), IPV (4th dose), Varicella (2nd dose)', date: new Date(birth.getTime() + 1825 * 24 * 60 * 60 * 1000), status: getVaccineStatus(new Date(birth.getTime() + 1825 * 24 * 60 * 60 * 1000), today) }
    ];
    
    const resultDiv = document.getElementById('vaccineSchedule');
    if (resultDiv) {
        resultDiv.style.display = 'block';
        resultDiv.innerHTML = `
            <div style="background: linear-gradient(135deg, #00b894 0%, #45a049 100%); color: white; padding: 25px; border-radius: 15px; margin-bottom: 20px;">
                <h3 style="margin-bottom: 15px; font-size: 22px;">AI Vaccine Schedule Generated</h3>
                <p style="margin-bottom: 10px;">Personalized vaccination schedule based on birth date and current age</p>
                <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 15px; margin-top: 20px;">
                    <div style="background: rgba(255,255,255,0.2); padding: 15px; border-radius: 10px; text-align: center;">
                        <div style="font-size: 20px; font-weight: bold;">${ageInMonths} months</div>
                        <div style="font-size: 12px;">Current Age</div>
                    </div>
                    <div style="background: rgba(255,255,255,0.2); padding: 15px; border-radius: 10px; text-align: center;">
                        <div style="font-size: 20px; font-weight: bold;">${schedule.filter(v => v.status === 'overdue').length}</div>
                        <div style="font-size: 12px;">Overdue</div>
                    </div>
                    <div style="background: rgba(255,255,255,0.2); padding: 15px; border-radius: 10px; text-align: center;">
                        <div style="font-size: 20px; font-weight: bold;">${schedule.filter(v => v.status === 'upcoming').length}</div>
                        <div style="font-size: 12px;">Upcoming</div>
                    </div>
                </div>
            </div>
            
            <div style="background: white; padding: 25px; border-radius: 15px; box-shadow: 0 10px 30px rgba(0,0,0,0.1); margin-bottom: 20px;">
                <h3 style="color: #00b894; margin-bottom: 20px;">Vaccination Timeline</h3>
                <div style="display: grid; gap: 15px;">
                    ${schedule.map(item => `
                        <div style="background: ${item.status === 'overdue' ? '#fff5f7' : item.status === 'due' ? '#fff5f7' : item.status === 'completed' ? '#ecfdf5' : '#f3f4f6'}; padding: 20px; border-radius: 10px; border-left: 4px solid ${item.status === 'overdue' ? '#ff4757' : item.status === 'due' ? '#ff9800' : item.status === 'completed' ? '#00b894' : '#9e9e9e'};">
                            <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 10px;">
                                <div>
                                    <div style="font-weight: 600; color: #0f2a56; font-size: 16px;">${item.age}</div>
                                    <div style="color: #666; margin-top: 5px;">${item.vaccines}</div>
                                </div>
                                <div style="background: ${item.status === 'overdue' ? '#ff4757' : item.status === 'due' ? '#ff9800' : item.status === 'completed' ? '#00b894' : '#9e9e9e'}; color: white; padding: 5px 15px; border-radius: 15px; font-size: 12px; text-transform: capitalize;">
                                    ${item.status}
                                </div>
                            </div>
                            <div style="color: #666; font-size: 14px;">
                                Target Date: ${item.date.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
                            </div>
                            ${item.status === 'overdue' ? '<div style="color: #ff4757; font-weight: 500; margin-top: 5px;">Contact healthcare provider immediately</div>' : ''}
                            ${item.status === 'due' ? '<div style="color: #ff9800; font-weight: 500; margin-top: 5px;">Schedule appointment soon</div>' : ''}
                        </div>
                    `).join('')}
                </div>
            </div>
            
            <div style="background: white; padding: 25px; border-radius: 15px; box-shadow: 0 10px 30px rgba(0,0,0,0.1);">
                <h3 style="color: #00b894; margin-bottom: 20px;">Important Vaccine Information</h3>
                <div style="display: grid; gap: 15px;">
                    <div style="background: #ecfdf5; padding: 15px; border-radius: 10px; border-left: 4px solid #00b894;">
                        <div style="color: #00d4aa; font-weight: 600; margin-bottom: 5px;">Vaccine Abbreviations:</div>
                        <div style="color: #666; font-size: 14px;">
                            <strong>DTaP:</strong> Diphtheria, Tetanus, Pertussis<br>
                            <strong>Hib:</strong> Haemophilus influenzae type b<br>
                            <strong>IPV:</strong> Inactivated Polio Vaccine<br>
                            <strong>PCV:</strong> Pneumococcal Conjugate Vaccine<br>
                            <strong>MMR:</strong> Measles, Mumps, Rubella<br>
                            <strong>Varicella:</strong> Chickenpox
                        </div>
                    </div>
                    <div style="background: #e3f2fd; padding: 15px; border-radius: 10px; border-left: 4px solid #00b894;">
                        <div style="color: #7c3aed; font-weight: 600; margin-bottom: 5px;">Important Reminders:</div>
                        <div style="color: #666; font-size: 14px;">
                            Always consult your healthcare provider for the most accurate schedule<br>
                            Some vaccines may be combined to reduce the number of injections<br>
                            Keep a record of all vaccinations received<br>
                            Report any adverse reactions to your healthcare provider
                        </div>
                    </div>
                </div>
            </div>
        `;
        
        resultDiv.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
}

function getVaccineStatus(vaccineDate, today) {
    const daysDiff = Math.floor((vaccineDate - today) / (24 * 60 * 60 * 1000));
    
    if (daysDiff < -30) return 'completed';
    if (daysDiff < 0) return 'overdue';
    if (daysDiff <= 30) return 'due';
    return 'upcoming';
}

// Advanced Fertility Diet Planning Function
async function buildAdvancedFertilityDietPlan() {
    const ageRange = document.getElementById('fertilityAgeRange')?.value;
    const dietStyle = document.getElementById('fertilityDietStyle')?.value;
    const goal = document.getElementById('fertilityDietGoal')?.value;
    const caffeine = document.getElementById('fertilityDietCaffeine')?.value;
    const hydration = document.getElementById('fertilityDietHydration')?.value;
    const activityLevel = document.getElementById('fertilityActivityLevel')?.value;
    const cycleLength = document.getElementById('fertilityCycleLength')?.value;
    const regularity = document.getElementById('fertilityRegularity')?.value;
    
    const healthConcerns = Array.from(document.querySelectorAll('input[type="checkbox"]:checked')).map(cb => cb.value);
    
    if (!ageRange || !dietStyle || !goal || !caffeine || !hydration || !activityLevel) {
        showNotification('Please complete all fields to generate your AI nutrition plan', 'warning');
        return;
    }
    
    // Show loading state
    const resultDiv = document.getElementById('fertilityDietResult');
    if (resultDiv) {
        resultDiv.style.display = 'block';
        resultDiv.innerHTML = `
            <div style="text-align: center; padding: 30px;">
                <div class="loading-spinner" style="display: inline-block; width: 30px; height: 30px; border: 3px solid #f3f3f3; border-top: 3px solid #ff6b9d; border-radius: 50%; animation: spin 1s linear infinite;"></div>
                <p style="margin-top: 20px; color: #666;">Generating AI-powered fertility analysis...</p>
            </div>
        `;
    }
    
    try {
        // Generate AI-powered fertility analysis
        const fertilityAnalysis = await generateAIFertilityAnalysis(ageRange, goal, healthConcerns, cycleLength, regularity);
        
        // Display results
        displayFertilityDietResults({
            personalInfo: { ageRange, goal },
            successMetrics: fertilityAnalysis.successMetrics,
            timeline: fertilityAnalysis.timeline,
            personalizedPlan: fertilityAnalysis.personalizedPlan
        });
        
        showNotification('AI Fertility Analysis Generated Successfully!', 'success');
    } catch (error) {
        console.error('AI Fertility Error:', error);
        // Fallback to original logic
        const nutritionPlan = generateAINutritionPlan(ageRange, dietStyle, goal, healthConcerns, caffeine, hydration, activityLevel);
        displayFertilityDietResults(nutritionPlan);
        showNotification('Using offline mode for fertility analysis', 'info');
    }
}

async function generateAIFertilityAnalysis(ageRange, goal, healthConcerns, cycleLength, regularity) {
    try {
        const response = await fetch(window.mamasafeApiUrl('/api/ai-fertility-analysis'), {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                ageRange,
                goal,
                healthConcerns: healthConcerns || [],
                cycleLength: cycleLength || 28,
                regularity: regularity || 'regular'
            })
        });

        if (!response.ok) {
            throw new Error('Failed to get AI analysis');
        }

        return await response.json();
    } catch (error) {
        console.error('AI Fertility Analysis Error:', error);
        throw error;
    }
}

