function generateSupplementPlan(goal, healthConcerns, ageRange) {
    const baseSupplements = ['Prenatal vitamin', 'Vitamin D3', 'Omega-3'];
    
    const goalSpecific = {
        'hormone-balance': ['Myo-inositol', 'Magnesium', 'Probiotics'],
        'egg-health': ['CoQ10', 'Vitamin E', 'Alpha-lipoic acid'],
        'sperm-health': ['Zinc', 'Selenium', 'L-carnitine'],
        'ovulation': ['Vitamin B6', 'Iron', 'Vitex'],
        'implantation': ['Vitamin K', 'Progesterone cream', 'Evening primrose oil'],
        'partner-support': ['Folic acid', 'Zinc', 'Selenium']
    };
    
    const healthSpecific = {
        pcos: ['Myo-inositol', 'Berberine', 'Cinnamon'],
        thyroid: ['Selenium', 'Iodine', 'L-tyrosine'],
        irregular: ['Vitex', 'Magnesium', 'B-vitamins'],
        endometriosis: ['Turmeric', 'Ginger', 'Omega-3']
    };
    
    const ageSpecific = {
        '20-25': ['Basic prenatal', 'Folic acid'],
        '26-30': ['Prenatal + DHA', 'CoQ10'],
        '31-35': ['High-potency prenatal', 'Myo-inositol', 'CoQ10'],
        '36-40': ['Advanced prenatal', 'DHEA', 'Ubiquinol'],
        '41+': ['Premium prenatal', 'CoQ10', 'Resveratrol', 'DHEA']
    };
    
    return {
        core: baseSupplements,
        goal: goalSpecific[goal] || [],
        health: healthConcerns.flatMap(concern => healthSpecific[concern] || []),
        age: ageSpecific[ageRange] || [],
        timing: 'Take supplements with meals for better absorption'
    };
}

function generateFertilityTimeline(ageRange, goal) {
    const timelines = {
        '20-25': {
            expectedImprovement: '2-3 months',
            optimalConception: '3-6 months',
            fullBenefits: '6-12 months'
        },
        '26-30': {
            expectedImprovement: '3-4 months',
            optimalConception: '4-8 months',
            fullBenefits: '8-12 months'
        },
        '31-35': {
            expectedImprovement: '4-6 months',
            optimalConception: '6-12 months',
            fullBenefits: '12-18 months'
        },
        '36-40': {
            expectedImprovement: '6-9 months',
            optimalConception: '9-18 months',
            fullBenefits: '18-24 months'
        },
        '41+': {
            expectedImprovement: '9-12 months',
            optimalConception: '12-24 months',
            fullBenefits: '24-36 months'
        }
    };
    
    return timelines[ageRange] || timelines['26-30'];
}

function calculateSuccessMetrics(ageRange, goal, healthConcerns) {
    const baseSuccess = {
        '20-25': 0.92,
        '26-30': 0.88,
        '31-35': 0.78,
        '36-40': 0.65,
        '41+': 0.45
    };
    
    const goalBonus = {
        'hormone-balance': 0.05,
        'egg-health': 0.03,
        'sperm-health': 0.04,
        'ovulation': 0.06,
        'implantation': 0.02,
        'partner-support': 0.07
    };
    
    const healthPenalties = {
        pcos: -0.15,
        thyroid: -0.10,
        irregular: -0.08,
        endometriosis: -0.12
    };
    
    let successRate = baseSuccess[ageRange] || 0.78;
    successRate += goalBonus[goal] || 0;
    
    healthConcerns.forEach(concern => {
        successRate += healthPenalties[concern] || 0;
    });
    
    successRate = Math.max(0.1, Math.min(0.95, successRate));
    
    return {
        successRate: Math.round(successRate * 100),
        improvementTime: '3-6 months',
        confidenceLevel: successRate > 0.7 ? 'High' : successRate > 0.5 ? 'Medium' : 'Requires Medical Support',
        recommendations: successRate < 0.5 ? 'Consider consulting fertility specialist' : 'Continue with current plan'
    };
}

