// Advanced Preconception Health Planning Function
function buildAdvancedPreconceptionPlan() {
    const age = document.getElementById('preconceptionAge')?.value;
    const health = document.getElementById('preconceptionHealth')?.value;
    const exercise = document.getElementById('preconceptionExercise')?.value;
    const meds = document.getElementById('preconceptionMeds')?.value;
    const stress = document.getElementById('preconceptionStress')?.value;
    const sleep = document.getElementById('preconceptionSleep')?.value;
    const diet = document.getElementById('preconceptionDiet')?.value;
    
    const lifestyleFactors = Array.from(document.querySelectorAll('input[type="checkbox"]:checked')).map(cb => cb.value);
    
    if (!age || !health || !exercise || !meds || !stress || !sleep || !diet) {
        showNotification('Please complete all fields to generate your AI health plan', 'warning');
        return;
    }
    
    // Generate AI-powered preconception plan
    const healthPlan = generateAIPreconceptionPlan(age, health, exercise, meds, stress, sleep, diet, lifestyleFactors);
    
    // Display results
    displayPreconceptionResults(healthPlan);
    
    // Update preview
    updatePreconceptionPreview(healthPlan);
    
    showNotification('AI Preconception Health Plan Generated Successfully!', 'success');
}

function generateAIPreconceptionPlan(age, health, exercise, meds, stress, sleep, diet, lifestyleFactors) {
    // AI-powered health optimization based on comprehensive analysis
    const healthScores = {
        excellent: 95,
        good: 80,
        fair: 60,
        poor: 40
    };
    
    const exerciseBenefits = {
        none: { score: -10, focus: 'Start with gentle walking and stretching' },
        light: { score: 5, focus: 'Add 2-3 days of moderate cardio' },
        moderate: { score: 10, focus: 'Maintain current routine with strength training' },
        active: { score: 15, focus: 'Excellent fitness level, add flexibility work' },
        'very-active': { score: 20, focus: 'Peak fitness, ensure adequate recovery' }
    };
    
    const stressImpact = {
        low: { score: 10, strategies: ['Continue stress management', 'Regular relaxation practices'] },
        moderate: { score: 0, strategies: ['Daily meditation', 'Yoga or tai chi', 'Nature walks'] },
        high: { score: -15, strategies: ['Professional counseling', 'Mindfulness training', 'Support groups'] },
        'very-high': { score: -25, strategies: ['Therapy recommended', 'Stress reduction program', 'Medical evaluation'] }
    };
    
    const sleepQuality = {
        excellent: { score: 15, focus: 'Optimal hormone regulation' },
        good: { score: 10, focus: 'Good hormone balance' },
        fair: { score: 5, focus: 'May affect ovulation' },
        poor: { score: -10, focus: 'Significant hormone disruption' }
    };
    
    const dietImpact = {
        balanced: { score: 10, focus: 'Optimal nutrient intake' },
        processed: { score: -15, focus: 'Reduce processed foods immediately' },
        'fast-food': { score: -20, focus: 'Major dietary changes needed' },
        organic: { score: 15, focus: 'Excellent nutritional foundation' },
        restricted: { score: 5, focus: 'Ensure complete protein profile' }
    };
    
    // Calculate base health score
    let healthScore = healthScores[health] || 60;
    healthScore += exerciseBenefits[exercise]?.score || 0;
    healthScore += stressImpact[stress]?.score || 0;
    healthScore += sleepQuality[sleep]?.score || 0;
    healthScore += dietImpact[diet]?.score || 0;
    
    // Apply lifestyle penalties
    lifestyleFactors.forEach(factor => {
        const penalties = {
            smoking: -20,
            alcohol: -15,
            caffeine: -5,
            'night-shift': -10
        };
        healthScore += penalties[factor] || 0;
    });
    
    // Generate comprehensive plan
    const recommendations = {
        personalInfo: {
            age: age,
            health: health,
            exercise: exercise,
            meds: meds,
            stress: stress,
            sleep: sleep,
            diet: diet,
            lifestyle: lifestyleFactors
        },
        healthScore: Math.max(0, Math.min(100, healthScore)),
        optimizationPlan: generateOptimizationPlan(healthScore, exercise, stress, sleep, diet),
        supplementPlan: generatePreconceptionSupplements(age, health, lifestyleFactors),
        timeline: generatePreconceptionTimeline(healthScore, age),
        riskFactors: identifyRiskFactors(health, lifestyleFactors),
        successMetrics: calculatePreconceptionSuccess(healthScore, age, health)
    };
    
    return recommendations;
}

function generateOptimizationPlan(healthScore, exercise, stress, sleep, diet) {
    const priorityAreas = [];
    
    if (healthScore < 70) {
        priorityAreas.push({
            area: 'Overall Health',
            priority: 'High',
            actions: ['Schedule comprehensive health checkup', 'Start prenatal vitamins', 'Implement lifestyle changes']
        });
    }
    
    if (exercise === 'none' || exercise === 'light') {
        priorityAreas.push({
            area: 'Physical Activity',
            priority: 'High',
            actions: ['Start with 15-20 minute daily walks', 'Add gentle stretching', 'Consider yoga or swimming']
        });
    }
    
    if (stress === 'high' || stress === 'very-high') {
        priorityAreas.push({
            area: 'Stress Management',
            priority: 'Critical',
            actions: ['Daily meditation practice', 'Consider professional counseling', 'Join support group', 'Practice mindfulness']
        });
    }
    
    if (sleep === 'poor' || sleep === 'fair') {
        priorityAreas.push({
            area: 'Sleep Optimization',
            priority: 'High',
            actions: ['Establish consistent sleep schedule', 'Create bedtime routine', 'Limit screen time before bed', 'Consider sleep study']
        });
    }
    
    if (diet === 'processed' || diet === 'fast-food') {
        priorityAreas.push({
            area: 'Nutrition Improvement',
            priority: 'High',
            actions: ['Increase whole foods intake', 'Reduce processed foods', 'Add more fruits and vegetables', 'Stay hydrated']
        });
    }
    
    return priorityAreas;
}

function generatePreconceptionSupplements(age, health, lifestyleFactors) {
    const baseSupplements = ['Prenatal vitamin', 'Folic acid (400-800mcg)', 'Vitamin D3 (1000-2000 IU)'];
    
    const healthSpecific = {
        excellent: [],
        good: ['Omega-3 (DHA 200-300mg)'],
        fair: ['CoQ10 (100-200mg)', 'Vitamin E (400 IU)'],
        poor: ['Iron supplement', 'B-complex', 'Magnesium (200-400mg)']
    };
    
    const lifestyleSpecific = [];
    if (lifestyleFactors.includes('smoking')) {
        lifestyleSpecific.push('Vitamin C (500-1000mg)', 'Zinc (15-30mg)');
    }
    if (lifestyleFactors.includes('alcohol')) {
        lifestyleSpecific.push('B-complex', 'Milk thistle');
    }
    
    const ageSpecific = {
        '20-25': baseSupplements,
        '26-30': [...baseSupplements, 'CoQ10 (100mg)'],
        '31-35': [...baseSupplements, 'CoQ10 (200mg)', 'DHEA (25-50mg)'],
        '36-40': [...baseSupplements, 'CoQ10 (300mg)', 'Ubiquinol', 'DHEA (50mg)'],
        '41+': [...baseSupplements, 'CoQ10 (300mg)', 'Ubiquinol', 'DHEA (75mg)', 'Resveratrol']
    };
    
    return {
        core: baseSupplements,
        health: healthSpecific[health] || [],
        lifestyle: lifestyleSpecific,
        age: ageSpecific[age] || baseSupplements,
        timing: 'Take with meals, avoid calcium at same time as iron',
        precautions: 'Consult healthcare provider before starting any new supplements'
    };
}

function generatePreconceptionTimeline(healthScore, age) {
    const baseTimelines = {
        '20-25': { optimization: '1-2 months', conception: '3-6 months', full: '6-12 months' },
        '26-30': { optimization: '2-3 months', conception: '4-8 months', full: '8-12 months' },
        '31-35': { optimization: '3-4 months', conception: '6-12 months', full: '12-18 months' },
        '36-40': { optimization: '4-6 months', conception: '9-18 months', full: '18-24 months' },
        '41+': { optimization: '6-9 months', conception: '12-24 months', full: '24-36 months' }
    };
    
    const healthAdjustments = {
        excellent: { multiplier: 0.8 },
        good: { multiplier: 1.0 },
        fair: { multiplier: 1.3 },
        poor: { multiplier: 1.6 }
    };
    
    const baseTimeline = baseTimelines[age] || baseTimelines['26-30'];
    const multiplier = healthAdjustments[healthScore >= 80 ? 'excellent' : healthScore >= 60 ? 'good' : healthScore >= 40 ? 'fair' : 'poor'];
    const adjustment = healthAdjustments[multiplier] || healthAdjustments['good'];
    
    return {
        optimization: adjustTimeline(baseTimeline.optimization, adjustment.multiplier),
        conception: adjustTimeline(baseTimeline.conception, adjustment.multiplier),
        full: adjustTimeline(baseTimeline.full, adjustment.multiplier)
    };
}

function adjustTimeline(baseTimeline, multiplier) {
    const months = parseInt(baseTimeline);
    const adjusted = Math.round(months * multiplier);
    return `${adjusted} months`;
}

function identifyRiskFactors(health, lifestyleFactors) {
    const risks = [];
    
    if (health === 'fair' || health === 'poor') {
        risks.push({
            factor: 'Health Status',
            level: health === 'poor' ? 'High' : 'Medium',
            description: 'Current health may impact fertility',
            recommendation: 'Schedule comprehensive health evaluation'
        });
    }
    
    if (lifestyleFactors.includes('smoking')) {
        risks.push({
            factor: 'Smoking',
            level: 'High',
            description: 'Smoking significantly impacts fertility',
            recommendation: 'Quit smoking immediately - seek support programs'
        });
    }
    
    if (lifestyleFactors.includes('alcohol')) {
        risks.push({
            factor: 'Alcohol Consumption',
            level: 'Medium',
            description: 'Alcohol can affect fertility',
            recommendation: 'Limit or eliminate alcohol consumption'
        });
    }
    
    if (lifestyleFactors.includes('night-shift')) {
        risks.push({
            factor: 'Night Shift Work',
            level: 'Medium',
            description: 'Circadian rhythm disruption',
            recommendation: 'Discuss schedule modifications with healthcare provider'
        });
    }
    
    return risks;
}

function calculatePreconceptionSuccess(healthScore, age, health) {
    const baseSuccess = {
        '20-25': 0.85,
        '26-30': 0.75,
        '31-35': 0.60,
        '36-40': 0.45,
        '41+': 0.25
    };
    
    const healthBonus = {
        excellent: 0.10,
        good: 0.05,
        fair: -0.05,
        poor: -0.15
    };
    
    let successRate = baseSuccess[age] || 0.60;
    successRate += healthBonus[health] || 0;
    
    successRate = Math.max(0.1, Math.min(0.95, successRate));
    
    return {
        successRate: Math.round(successRate * 100),
        confidenceLevel: successRate > 0.7 ? 'High' : successRate > 0.5 ? 'Medium' : 'Consult Specialist',
        timeframe: successRate > 0.7 ? '3-6 months' : successRate > 0.5 ? '6-12 months' : '12+ months',
        recommendations: successRate < 0.5 ? 'Consider fertility specialist consultation' : 'Continue with optimization plan'
    };
}

