function generateCourseRecommendations() {
    const stage = document.getElementById('assessmentStage').value;
    const goals = Array.from(document.querySelectorAll('.goal-checkbox:checked')).map(cb => cb.value);
    const preference = document.getElementById('assessmentPreference').value;
    const experience = document.getElementById('assessmentExperience').value;
    
    if (!stage) {
        alert('Please select your pregnancy stage');
        return;
    }
    
    // Update course manager state
    window.courseManager.setPregnancyStage(stage);
    window.courseManager.setLearningGoals(goals);
    window.courseManager.setLearningPace(preference);
    
    // Get recommendations
    const recommendations = window.courseManager.getAIRecommendations();
    
    // Close current modal
    document.querySelector('.course-modal').remove();
    
    // Show recommendations modal
    showRecommendationsModal(recommendations, stage, goals, preference);
}

function showRecommendationsModal(recommendations, stage, goals, preference) {
    const modal = document.createElement('div');
    modal.className = 'course-modal';
    modal.innerHTML = `
        <div class="course-modal-content">
            <div class="course-modal-header">
                <h2 class="course-modal-title">Your Personalized Learning Path</h2>
                <button class="course-modal-close" onclick="this.closest('.course-modal').remove()">×</button>
            </div>
            <div class="course-modal-body">
                <div style="text-align: center; margin-bottom: 30px;">
                    <div style="background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); width: 80px; height: 80px; border-radius: 50%; display: flex; align-items: center; justify-content: center; margin: 0 auto 20px; font-size: 32px;">AI</div>
                    <h3 style="margin-bottom: 10px; color: #0f2a56;">AI-Curated Courses</h3>
                    <p style="color: #666;">Based on your ${stage} stage and ${goals.length} learning goals</p>
                </div>
                
                <div style="background: #f8f9fa; padding: 20px; border-radius: 15px; margin-bottom: 25px;">
                    <h4 style="color: #0f2a56; margin-bottom: 15px;">Recommended Courses</h4>
                    ${recommendations.length > 0 ? recommendations.map(course => `
                        <div style="background: white; border: 2px solid #e9ecef; padding: 20px; border-radius: 15px; margin-bottom: 15px; display: flex; justify-content: space-between; align-items: center;">
                            <div>
                                <div style="display: flex; align-items: center; gap: 10px; margin-bottom: 8px;">
                                    <span style="font-size: 32px;">${course.thumbnail}</span>
                                    <strong style="color: #0f2a56;">${course.title}</strong>
                                </div>
                                <div style="color: #666; font-size: 14px;">${course.lessons} lessons • ${course.duration} • ⭐ ${course.rating}</div>
                            </div>
                            <button onclick="enrollInCourse('${course.id}')" style="background: #667eea; color: white; padding: 10px 20px; border: none; border-radius: 10px; cursor: pointer; font-weight: 600;">Enroll</button>
                        </div>
                    `).join('') : '<p style="color: #666;">No courses available for your selection. Try adjusting your preferences.</p>'}
                </div>
                
                <div style="background: #e3f2fd; padding: 20px; border-radius: 15px; margin-bottom: 25px;">
                    <h4 style="color: #7c3aed; margin-bottom: 15px;">AI Insights</h4>
                    <p style="color: #7c3aed; font-size: 14px; line-height: 1.6;">
                        Based on your ${stage} stage and ${goals.length} learning goals, we've selected ${recommendations.length} courses that match your ${preference} learning style. This personalized path will help you achieve your motherhood goals with confidence.
                    </p>
                </div>
            </div>
            <div style="display: flex; gap: 15px;">
                <button onclick="enrollAllRecommended('${JSON.stringify(recommendations.map(r => r.id))}')" style="flex: 1; background: #667eea; color: white; padding: 15px; border: none; border-radius: 10px; font-weight: 600; cursor: pointer;">Enroll All</button>
                <button onclick="this.closest('.course-modal').remove()" style="flex: 1; background: #f8f9fa; color: #0f2a56; padding: 15px; border: none; border-radius: 10px; font-weight: 600; cursor: pointer;">Save for Later</button>
            </div>
        </div>
    `;
    
    document.body.appendChild(modal);
}

function enrollInCourse(courseId) {
    console.log('Enrolling in course:', courseId);
    
    if (!window.courseManager) {
        console.error('CourseManager not available');
        showNotification('Error: Course system not loaded', 'error');
        return;
    }
    
    const enrolled = window.courseManager.enrollInCourse(courseId);
    console.log('Enrollment result:', enrolled);
    
    if (enrolled) {
        showNotification('Successfully enrolled in course!', 'success');
        updateLearningStats();
        // Refresh course grid to show enrollment status
        const featuredCourses = window.courseManager.getFeaturedCourses();
        renderCourseGrid(featuredCourses);
    } else {
        showNotification('Already enrolled in this course', 'info');
    }
}

function enrollAllRecommended(courseIds) {
    if (!window.courseManager) return;
    
    const ids = JSON.parse(courseIds);
    let enrolledCount = 0;
    
    ids.forEach(id => {
        if (window.courseManager.enrollInCourse(id)) {
            enrolledCount++;
        }
    });
    
    showNotification(`Enrolled in ${enrolledCount} courses!`, 'success');
    document.querySelector('.course-modal').remove();
    updateLearningStats();
}

function showAllCourses() {
    if (!window.courseManager) return;
    
    const courses = window.courseManager.getAllCourses();
    renderCourseGrid(courses);
}

function renderCourseGrid(courses) {
    console.log('renderCourseGrid called with', courses.length, 'courses');
    const container = document.getElementById('featuredCourses');
    if (!container) {
        console.error('featuredCourses container not found');
        return;
    }
    
    container.innerHTML = courses.map(course => {
        const isEnrolled = window.courseManager.isEnrolled(course.id);
        const progress = window.courseManager.getCourseProgress(course.id);
        console.log(`Course ${course.id} enrolled:`, isEnrolled, 'progress:', progress);
        
        return `
            <div class="course-card" onclick="showCourseDetail('${course.id}')">
                <div class="course-card-header" style="background: linear-gradient(135deg, ${course.color} 0%, ${course.color}99 100%);">
                    <span style="font-size: 64px;">${course.thumbnail}</span>
                    ${course.tags.map(tag => `<span class="course-badge" style="color: ${course.color}">${tag.toUpperCase()}</span>`).join('')}
                </div>
                <div class="course-card-body">
                    <div class="course-tags">
                        ${course.tags.map(tag => `<span class="course-tag" style="background: ${course.color}20; color: ${course.color}">${tag}</span>`).join('')}
                    </div>
                    <h3 class="course-card-title">${course.title}</h3>
                    <p class="course-card-description">${course.description}</p>
                    
                    ${isEnrolled ? `
                        <div class="progress-bar">
                            <div class="progress-fill" style="width: ${progress.progress}%"></div>
                        </div>
                        <div style="font-size: 13px; color: #666; margin-bottom: 15px;">${progress.progress.toFixed(0)}% complete</div>
                    ` : ''}
                    
                    <div class="course-stats">
                        <div class="course-stat">
                            <div class="course-stat-value" style="color: ${course.color}">${course.lessons}</div>
                            <div class="course-stat-label">Lessons</div>
                        </div>
                        <div class="course-stat">
                            <div class="course-stat-value" style="color: ${course.color}">${course.duration}</div>
                            <div class="course-stat-label">Duration</div>
                        </div>
                    </div>
                    
                    <div class="course-card-footer">
                        <div class="course-rating">
                            <span>⭐</span>
                            <span class="course-rating-value">${course.rating}</span>
                            <span class="course-rating-reviews">(${(course.reviews / 1000).toFixed(1)}k)</span>
                        </div>
                        <div class="course-enrolled">👥 ${course.enrolled.toLocaleString()}</div>
                    </div>
                    
                    <button class="course-btn" onclick="event.stopPropagation(); ${isEnrolled ? `continueCourse('${course.id}')` : `enrollInCourse('${course.id}')`}" style="background: ${course.color}; color: white; width: 100%; margin-top: 15px;">
                        ${isEnrolled ? 'Continue Learning' : 'Start Learning'}
                    </button>
                </div>
            </div>
        `;
    }).join('');
}

function showCourseDetail(courseId) {
    if (!window.courseManager) return;
    
    const course = window.courseManager.getCourseById(courseId);
    if (!course) return;
    
    const isEnrolled = window.courseManager.isEnrolled(courseId);
    const progress = window.courseManager.getCourseProgress(courseId);
    
    const modal = document.createElement('div');
    modal.className = 'course-modal';
    modal.innerHTML = `
        <div class="course-modal-content">
            <div class="course-modal-header">
                <h2 class="course-modal-title">${course.title}</h2>
                <button class="course-modal-close" onclick="this.closest('.course-modal').remove()">×</button>
            </div>
            <div class="course-modal-body">
                <div style="background: linear-gradient(135deg, ${course.color} 0%, ${course.color}99 100%); padding: 30px; border-radius: 15px; margin-bottom: 30px; text-align: center;">
                    <span style="font-size: 64px;">${course.thumbnail}</span>
                    <p style="color: white; margin-top: 15px; font-size: 18px;">${course.description}</p>
                </div>
                
                <div style="display: grid; grid-template-columns: repeat(3, 1fr); gap: 15px; margin-bottom: 30px;">
                    <div style="text-align: center; padding: 15px; background: #f8f9fa; border-radius: 10px;">
                        <div style="font-size: 24px; font-weight: bold; color: ${course.color};">${course.lessons}</div>
                        <div style="font-size: 13px; color: #666;">Lessons</div>
                    </div>
                    <div style="text-align: center; padding: 15px; background: #f8f9fa; border-radius: 10px;">
                        <div style="font-size: 24px; font-weight: bold; color: ${course.color};">${course.duration}</div>
                        <div style="font-size: 13px; color: #666;">Duration</div>
                    </div>
                    <div style="text-align: center; padding: 15px; background: #f8f9fa; border-radius: 10px;">
                        <div style="font-size: 24px; font-weight: bold; color: ${course.color};">⭐ ${course.rating}</div>
                        <div style="font-size: 13px; color: #666;">Rating</div>
                    </div>
                </div>
                
                ${isEnrolled ? `
                    <div style="margin-bottom: 30px;">
                        <h4 style="margin-bottom: 15px; color: #0f2a56;">Course Progress</h4>
                        <div class="progress-bar">
                            <div class="progress-fill" style="width: ${progress.progress}%"></div>
                        </div>
                        <div style="font-size: 14px; color: #666;">${progress.progress.toFixed(0)}% complete</div>
                    </div>
                ` : ''}
                
                <h4 style="margin-bottom: 15px; color: #0f2a56;">Course Modules</h4>
                ${course.modules.map((module, index) => {
                    const isCompleted = progress.completedModules?.includes(module.id);
                    return `
                        <div class="course-module ${isCompleted ? 'completed' : ''}" onclick="completeModule('${courseId}', ${module.id})">
                            <div>
                                <div class="course-module-title">${module.title}</div>
                                <div class="course-module-duration">${module.duration}</div>
                            </div>
                            ${isCompleted ? '<span class="course-module-check">✓</span>' : ''}
                        </div>
                    `;
                }).join('')}
            </div>
            <div style="display: flex; gap: 15px;">
                <button onclick="${isEnrolled ? `continueCourse('${courseId}')` : `enrollInCourse('${courseId}')`}" style="flex: 1; background: ${course.color}; color: white; padding: 15px; border: none; border-radius: 10px; font-weight: 600; cursor: pointer;">
                    ${isEnrolled ? 'Continue Learning' : 'Enroll Now'}
                </button>
                <button onclick="this.closest('.course-modal').remove()" style="flex: 1; background: #f8f9fa; color: #0f2a56; padding: 15px; border: none; border-radius: 10px; font-weight: 600; cursor: pointer;">Close</button>
            </div>
        </div>
    `;
    
    document.body.appendChild(modal);
}

// Course UI: see js/features/courses-ui.js (modules, modals, dashboard)

function ensureUi() {}

function showNotification(message, type = 'info') {
    if (typeof addAppNotification === 'function') {
        addAppNotification(message, type);
    }

    const notification = document.createElement('div');
    notification.style.cssText = `
        position: fixed;
        top: 20px;
        right: 20px;
        background: ${type === 'success' ? '#00b894' : '#667eea'};
        color: white;
        padding: 15px 25px;
        border-radius: 10px;
        box-shadow: 0 5px 15px rgba(0,0,0,0.2);
        z-index: 10001;
        animation: slideIn 0.3s ease;
    `;
    notification.textContent = message;
    
    document.body.appendChild(notification);

    setTimeout(() => {
        notification.style.animation = 'slideOut 0.3s ease';
        setTimeout(() => notification.remove(), 300);
    }, 3000);
}

function closeModal() {
    if (window.currentModal) {
        window.currentModal.remove();
        window.currentModal = null;
    }
}

