// Generate comprehensive health analysis
function generateHealthAnalysis(age, temperature, symptoms) {
    // Temperature analysis
    const tempStatus = temperature >= 37.5 ? 'high' : temperature >= 37.0 ? 'elevated' : temperature >= 36.5 ? 'normal' : 'low';
    const tempStatusText = {
        high: 'High fever detected - immediate attention required',
        elevated: 'Elevated temperature - monitor closely',
        normal: 'Normal temperature range',
        low: 'Below normal - ensure warmth'
    }[tempStatus];
    
    const tempRecommendation = {
        high: 'Administer fever reducer and seek immediate medical attention',
        elevated: 'Monitor temperature every 2 hours, consider fever reducer',
        normal: 'Continue monitoring, maintain hydration',
        low: 'Ensure adequate warmth, recheck temperature in 30 minutes'
    }[tempStatus];
    
    // Symptom severity calculation
    const totalSymptoms = symptoms.respiratory.length + symptoms.general.length + symptoms.digestive.length;
    const severityScore = Math.min(totalSymptoms * 2, 10);
    const severityLevel = severityScore >= 7 ? 'high' : severityScore >= 4 ? 'medium' : 'low';
    const severityLevelText = {
        high: 'High Severity - Medical consultation recommended',
        medium: 'Moderate Severity - Monitor closely',
        low: 'Low Severity - Home care may be sufficient'
    }[severityLevel];
    
    // Risk assessment
    const riskScore = Math.max(
        tempStatus === 'high' ? 80 : tempStatus === 'elevated' ? 60 : 20,
        severityScore * 8,
        age < 6 ? 30 : age < 12 ? 20 : 10
    );
    const riskLevel = riskScore >= 70 ? 'critical' : riskScore >= 50 ? 'high' : riskScore >= 30 ? 'medium' : 'low';
    const riskLevelText = {
        critical: 'Critical - Seek immediate medical attention',
        high: 'High Risk - Consult healthcare provider soon',
        medium: 'Medium Risk - Monitor and consider consultation',
        low: 'Low Risk - Home monitoring appropriate'
    }[riskLevel];
    
    const riskIcon = {
        critical: '🚨',
        high: '⚠️',
        medium: '⚡',
        low: '✅'
    }[riskLevel];
    
    const riskFactors = [];
    if (tempStatus === 'high') riskFactors.push('High fever');
    if (severityScore >= 6) riskFactors.push('Multiple symptoms');
    if (age < 6) riskFactors.push('Young age');
    if (symptoms.respiratory.length > 0) riskFactors.push('Respiratory symptoms');
    
    // Symptom analysis
    const symptomAnalysis = {
        respiratory: {
            icon: '🗣️',
            count: symptoms.respiratory.length,
            severity: symptoms.respiratory.length >= 2 ? 'high' : symptoms.respiratory.length >= 1 ? 'medium' : 'low',
            severityText: symptoms.respiratory.length >= 2 ? 'Multiple respiratory issues' : symptoms.respiratory.length >= 1 ? 'Respiratory concern' : 'Clear breathing',
            analysis: symptoms.respiratory.length >= 2 ? 'Multiple respiratory symptoms indicate possible infection' : 
                     symptoms.respiratory.length >= 1 ? 'Single respiratory symptom - monitor for progression' : 
                     'No respiratory issues detected'
        },
        general: {
            icon: '🏥',
            count: symptoms.general.length,
            severity: symptoms.general.length >= 2 ? 'high' : symptoms.general.length >= 1 ? 'medium' : 'low',
            severityText: symptoms.general.length >= 2 ? 'Multiple general symptoms' : symptoms.general.length >= 1 ? 'General concern' : 'No general symptoms',
            analysis: symptoms.general.length >= 2 ? 'Multiple general symptoms suggest systemic issue' : 
                     symptoms.general.length >= 1 ? 'General symptom present - monitor overall health' : 
                     'No general health concerns'
        },
        digestive: {
            icon: '💩',
            count: symptoms.digestive.length,
            severity: symptoms.digestive.length >= 2 ? 'high' : symptoms.digestive.length >= 1 ? 'medium' : 'low',
            severityText: symptoms.digestive.length >= 2 ? 'Multiple digestive issues' : symptoms.digestive.length >= 1 ? 'Digestive concern' : 'No digestive issues',
            analysis: symptoms.digestive.length >= 2 ? 'Multiple digestive symptoms indicate GI disturbance' : 
                     symptoms.digestive.length >= 1 ? 'Single digestive symptom - monitor hydration' : 
                     'No digestive concerns detected'
        }
    };
    
    // Generate recommendations
    const recommendations = [];
    
    if (tempStatus === 'high') {
        recommendations.push({
            priority: 'high',
            icon: '🚨',
            title: 'Emergency Care Required',
            description: 'High fever detected - seek immediate medical attention at emergency room',
            urgency: 'Immediate - Within 1 hour'
        });
    } else if (tempStatus === 'elevated') {
        recommendations.push({
            priority: 'medium',
            icon: '🌡️',
            title: 'Fever Management',
            description: 'Monitor temperature every 2 hours, consider age-appropriate fever reducer',
            urgency: 'Urgent - Within 4 hours'
        });
    }
    
    if (severityScore >= 6) {
        recommendations.push({
            priority: 'high',
            icon: '👨‍⚕️',
            title: 'Medical Consultation',
            description: 'Multiple symptoms present - professional medical evaluation recommended',
            urgency: 'Urgent - Within 24 hours'
        });
    }
    
    if (symptoms.respiratory.length > 0) {
        recommendations.push({
            priority: 'medium',
            icon: '💨',
            title: 'Respiratory Care',
            description: 'Monitor breathing, use humidifier, ensure adequate hydration',
            urgency: 'Monitor - Daily'
        });
    }
    
    recommendations.push({
        priority: 'low',
        icon: '💧',
        title: 'Hydration & Comfort',
        description: 'Maintain fluid intake, ensure rest, monitor for changes',
        urgency: 'Continuous'
    });
    
    return {
        temperature: {
            value: temperature,
            status: tempStatus,
            statusText: tempStatusText,
            recommendation: tempRecommendation
        },
        symptomSeverity: {
            score: severityScore,
            percentage: severityScore * 10,
            level: severityLevel,
            levelText: severityLevelText
        },
        riskAssessment: {
            score: riskScore,
            level: riskLevel,
            levelText: riskLevelText,
            icon: riskIcon,
            factors: riskFactors
        },
        symptomAnalysis,
        recommendations
    };
}

