// Generate advanced nutrition plan
function generateAdvancedNutritionPlan(age, weight, feedingMethod, restrictions, additionalAllergies) {
    // Determine age group
    const ageGroup = age < 6 ? '0-6 months' : age < 12 ? '6-12 months' : age < 18 ? '12-18 months' : '18-24 months';
    const ageDescription = {
        '0-6 months': 'Infant - Breastmilk/formula only',
        '6-12 months': 'Young Toddler - Introduction to solids',
        '12-18 months': 'Toddler - Varied diet',
        '18-24 months': 'Preschooler - Family foods'
    }[ageGroup];
    
    // Calculate daily calories
    const dailyCalories = Math.round((weight * 100) + (age * 10));
    
    // Determine meal frequency
    const mealFrequency = age < 6 ? '6-8 feeds' : age < 12 ? '3 meals + 2 snacks' : age < 18 ? '3 meals + 1 snack' : '3 meals';
    const feedingSchedule = age < 6 ? 'Every 2-3 hours' : age < 12 ? 'Small frequent meals' : age < 18 ? 'Regular meal times' : 'Family meal schedule';
    
    // Generate nutrient analysis
    const nutrients = [
        {
            name: 'Protein',
            icon: '🥩',
            amount: `${Math.round(weight * 1.5)}g/day`,
            percentage: Math.min(Math.round((weight * 1.5) / (weight * 2) * 100), 100),
            status: Math.round(weight * 1.5) >= weight * 1.2 ? 'excellent' : 'good',
            statusText: Math.round(weight * 1.5) >= weight * 1.2 ? 'Excellent' : 'Good',
            sources: restrictions.vegetarian ? 'Lentils, beans, quinoa, tofu' : 'Lean meat, fish, eggs, dairy'
        },
        {
            name: 'Iron',
            icon: '��',
            amount: `${Math.round(weight * 0.2)}mg/day`,
            percentage: Math.min(Math.round((weight * 0.2) / (weight * 0.3) * 100), 100),
            status: Math.round(weight * 0.2) >= weight * 0.15 ? 'excellent' : 'good',
            statusText: Math.round(weight * 0.2) >= weight * 0.15 ? 'Excellent' : 'Good',
            sources: restrictions.vegetarian ? 'Spinach, lentils, fortified cereals' : 'Red meat, poultry, fish, beans'
        },
        {
            name: 'Calcium',
            icon: '🥛',
            amount: `${Math.round(weight * 50)}mg/day`,
            percentage: Math.min(Math.round((weight * 50) / (weight * 60) * 100), 100),
            status: restrictions.dairyFree ? 'needs-attention' : Math.round(weight * 50) >= weight * 40 ? 'excellent' : 'good',
            statusText: restrictions.dairyFree ? 'Supplement Recommended' : Math.round(weight * 50) >= weight * 40 ? 'Excellent' : 'Good',
            sources: restrictions.dairyFree ? 'Fortified plant milks, leafy greens, tofu' : 'Dairy products, fortified foods, leafy greens'
        },
        {
            name: 'Vitamin D',
            icon: '☀️',
            amount: '400 IU/day',
            percentage: 100,
            status: 'excellent',
            statusText: 'Supplemented',
            sources: 'Sunlight, fortified milk, supplements'
        },
        {
            name: 'Omega-3',
            icon: '🐟',
            amount: `${Math.round(weight * 30)}mg/day`,
            percentage: Math.min(Math.round((weight * 30) / (weight * 40) * 100), 100),
            status: Math.round(weight * 30) >= weight * 25 ? 'excellent' : 'good',
            statusText: Math.round(weight * 30) >= weight * 25 ? 'Excellent' : 'Good',
            sources: restrictions.vegetarian ? 'Flaxseed, chia seeds, walnuts' : 'Fatty fish, fish oil, walnuts'
        }
    ];
    
    // Generate meal plan
    const mealPlan = [];
    
    if (age >= 6) {
        mealPlan.push({
            name: 'Morning Puree',
            icon: '🥣',
            time: '8:00 AM',
            ingredients: restrictions.dairyFree ? 
                ['Sweet potato', 'Carrot', 'Apple puree'] : 
                ['Oatmeal', 'Banana', 'Yogurt'],
            calories: '120-150',
            protein: '3-4g',
            iron: '1.2mg',
            preparation: 'Steam vegetables, blend until smooth, cool to safe temperature',
            allergenAlert: restrictions.dairyFree ? 'Contains dairy alternatives' : null
        });
        
        mealPlan.push({
            name: 'Mid-Morning Snack',
            icon: '🍌',
            time: '10:30 AM',
            ingredients: restrictions.nutFree ? 
                ['Soft fruit pieces', 'Rice crackers'] : 
                ['Soft fruit pieces', 'Avocado', 'Mild cheese'],
            calories: '80-100',
            protein: '1-2g',
            iron: '0.8mg',
            preparation: 'Cut into small, manageable pieces to prevent choking',
            allergenAlert: restrictions.nutFree ? 'Nut-free alternatives used' : null
        });
        
        mealPlan.push({
            name: 'Lunch Meal',
            icon: '🍛',
            time: '12:30 PM',
            ingredients: restrictions.vegetarian ? 
                ['Lentil puree', 'Quinoa', 'Steamed vegetables'] : 
                ['Chicken puree', 'Sweet potato', 'Green beans'],
            calories: '180-220',
            protein: '6-8g',
            iron: '2.5mg',
            preparation: 'Cook proteins thoroughly, mix with vegetables for complete meal',
            allergenAlert: null
        });
        
        mealPlan.push({
            name: 'Afternoon Snack',
            icon: '🍓',
            time: '3:00 PM',
            ingredients: restrictions.glutenFree ? 
                ['Berries', 'Yogurt', 'Rice cakes'] : 
                ['Berries', 'Whole grain crackers', 'Cheese'],
            calories: '100-120',
            protein: '2-3g',
            iron: '1.0mg',
            preparation: 'Fresh berries washed thoroughly, serve at room temperature',
            allergenAlert: restrictions.glutenFree ? 'Gluten-free crackers' : null
        });
        
        mealPlan.push({
            name: 'Dinner Meal',
            icon: '🍽',
            time: '6:00 PM',
            ingredients: restrictions.vegetarian ? 
                ['Bean and vegetable stew', 'Brown rice', 'Avocado'] : 
                ['Fish and vegetable puree', 'Mashed potatoes', 'Peas'],
            calories: '200-250',
            protein: '8-10g',
            iron: '3.0mg',
            preparation: 'Ensure fish is deboned, vegetables are well-cooked and mashed',
            allergenAlert: null
        });
    }
    
    return {
        ageGroup,
        ageDescription,
        dailyCalories,
        mealFrequency,
        feedingSchedule,
        nutrients,
        mealPlan,
        restrictions,
        additionalAllergies
    };
}

