// Generate advanced sleep analysis using AI
async function generateAdvancedSleepAnalysisAI(age, duration, quality, environment, associations, concerns) {
    try {
        const response = await fetch(window.mamasafeApiUrl('/api/ai-sleep-analysis'), {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                age: parseInt(age),
                sleepDuration: duration,
                sleepQuality: quality,
                sleepEnvironment: environment,
                concerns: concerns || ''
            })
        });

        if (!response.ok) {
            throw new Error('Failed to get AI analysis');
        }

        return await response.json();
    } catch (error) {
        console.error('AI Sleep Analysis Error:', error);
        // Fallback to original logic
        return generateAdvancedSleepAnalysisFallback(age, duration, quality, environment, associations, concerns);
    }
}

// Generate advanced sleep analysis (fallback)
function generateAdvancedSleepAnalysisFallback(age, duration, quality, environment, associations, concerns) {
    // Calculate sleep quality score
    const qualityScores = { excellent: 9, good: 7, fair: 5, poor: 3 };
    const baseScore = qualityScores[quality] || 5;
    
    // Adjust score based on concerns
    let finalScore = baseScore;
    if (concerns.frequentWaking) finalScore -= 2;
    if (concerns.difficultyFalling) finalScore -= 2;
    if (concerns.nightTerrors) finalScore -= 3;
    if (concerns.restlessSleep) finalScore -= 1;
    if (concerns.snoring) finalScore -= 1;
    
    // Calculate environment score
    let environmentScore = 7;
    if (environment.darkRoom) environmentScore += 1;
    if (environment.quietRoom) environmentScore += 1;
    if (environment.coolTemp) environmentScore += 1;
    if (environment.whiteNoise) environmentScore += 1;
    
    // Calculate circadian health
    const expectedSleep = age < 6 ? 14 : age < 12 ? 12 : age < 18 ? 11 : 10;
    const circadianHealth = Math.min(Math.round((duration / expectedSleep) * 100), 150);
    
    // Determine status
    const qualityStatus = finalScore >= 8 ? 'Excellent' : finalScore >= 6 ? 'Good' : finalScore >= 4 ? 'Fair' : 'Needs Improvement';
    const circadianStatus = circadianHealth >= 90 ? 'Optimal' : circadianHealth >= 75 ? 'Good' : circadianHealth >= 60 ? 'Fair' : 'Needs Attention';
    const environmentStatus = environmentScore >= 9 ? 'Excellent' : environmentScore >= 7 ? 'Good' : environmentScore >= 5 ? 'Fair' : 'Poor';
    
    // Generate sleep patterns
    const sleepPatterns = [];
    
    if (concerns.frequentWaking) {
        sleepPatterns.push({
            name: 'Sleep Fragmentation',
            icon: '🔄',
            status: 'warning',
            statusText: 'Detected',
            description: 'Frequent night waking detected, indicating poor sleep consolidation',
            recommendation: 'Establish consistent bedtime routine and ensure optimal sleep environment',
            urgency: 'high',
            urgencyText: 'Immediate attention needed'
        });
    }
    
    if (concerns.difficultyFalling) {
        sleepPatterns.push({
            name: 'Sleep Onset Issues',
            icon: '😴',
            status: 'warning',
            statusText: 'Detected',
            description: 'Difficulty falling asleep suggests overstimulation or inconsistent routine',
            recommendation: 'Implement wind-down routine 30-45 minutes before bedtime',
            urgency: 'medium',
            urgencyText: 'Address soon'
        });
    }
    
    if (concerns.nightTerrors) {
        sleepPatterns.push({
            name: 'Night Terrors',
            icon: '😱',
            status: 'critical',
            statusText: 'Detected',
            description: 'Night terrors detected, may indicate stress or developmental stage',
            recommendation: 'Ensure safe sleep environment and consider consultation if persistent',
            urgency: 'high',
            urgencyText: 'Monitor closely'
        });
    }
    
    if (concerns.snoring) {
        sleepPatterns.push({
            name: 'Snoring',
            icon: '💤',
            status: 'warning',
            statusText: 'Detected',
            description: 'Snoring may indicate airway obstruction or sleep position issues',
            recommendation: 'Check sleep position and consult pediatrician if persistent',
            urgency: 'medium',
            urgencyText: 'Medical evaluation recommended'
        });
    }
    
    // Generate recommendations
    const recommendations = [];
    
    if (finalScore < 6) {
        recommendations.push({
            priority: 'high',
            icon: '🏠',
            title: 'Sleep Environment Optimization',
            description: 'Improve sleep environment with dark, quiet, and cool conditions',
            ageRange: 'All ages'
        });
    }
    
    if (duration < expectedSleep * 0.8) {
        recommendations.push({
            priority: 'high',
            icon: '⏰',
            title: 'Extend Sleep Duration',
            description: 'Gradually extend sleep time by 15-30 minutes to meet age-appropriate needs',
            ageRange: `${age} months`
        });
    }
    
    if (!environment.darkRoom) {
        recommendations.push({
            priority: 'medium',
            icon: '🌃',
            title: 'Dark Room Setup',
            description: 'Install blackout curtains and remove light sources from sleep area',
            ageRange: 'All ages'
        });
    }
    
    if (!associations.swaddling && age < 6) {
        recommendations.push({
            priority: 'medium',
            icon: '👶',
            title: 'Swaddling Technique',
            description: 'Consider swaddling for better sleep security and reduced startle reflex',
            ageRange: '0-6 months'
        });
    }
    
    recommendations.push({
        priority: 'low',
        icon: '📊',
        title: 'Sleep Tracking',
        description: 'Maintain sleep diary to identify patterns and track improvements',
        ageRange: 'All ages'
    });
    
    return {
        qualityScore: Math.min(Math.max(finalScore, 1), 10),
        qualityStatus,
        circadianHealth,
        circadianStatus,
        environmentScore: Math.min(environmentScore, 10),
        environmentStatus,
        sleepPatterns,
        recommendations
    };
}

// Download sleep report
function downloadSleepReport() {
    if (!window.sleepAnalysisData) {
        showNotification('No sleep analysis data available', 'error');
        return;
    }
    
    const data = window.sleepAnalysisData;
    const content = `
NEURAL SLEEP INTELLIGENCE REPORT
=====================================

Analysis Date: ${new Date().toLocaleString()}
AI Model: Sleep Intelligence System v2.0

SLEEP OVERVIEW
===============
Sleep Quality Score: ${data.qualityScore}/10
Quality Status: ${data.qualityStatus}
Circadian Health: ${data.circadianHealth}%
Circadian Status: ${data.circadianStatus}
Environment Score: ${data.environmentScore}/10
Environment Status: ${data.environmentStatus}

SLEEP PATTERN ANALYSIS
=======================
${data.sleepPatterns.map(pattern => `
${pattern.name}:
- Status: ${pattern.statusText}
- Description: ${pattern.description}
- Recommendation: ${pattern.recommendation}
- Urgency: ${pattern.urgencyText}
`).join('')}

AI RECOMMENDATIONS
==================
${data.recommendations.map(rec => `${rec.title}: ${rec.description} (${rec.ageRange})`).join('\n')}

Generated by Mamasafe Sleep AI
Disclaimer: This sleep analysis is for informational purposes only. Always consult with your pediatrician for sleep concerns.
    `;
    
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `sleep-analysis-${new Date().toISOString().split('T')[0]}.txt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    
    showNotification('Sleep report downloaded successfully!', 'success');
}

// Share sleep results
function shareSleepResults() {
    if (!window.sleepAnalysisData) {
        showNotification('No sleep analysis data available', 'error');
        return;
    }
    
    const data = window.sleepAnalysisData;
    const shareText = `Sleep Analysis: ${data.qualityScore}/10 quality score, ${data.circadianHealth}% circadian health, ${data.qualityStatus} status`;
    
    if (navigator.share) {
        navigator.share({
            title: 'Sleep Analysis AI Results',
            text: shareText,
            url: window.location.href
        }).then(() => {
            showNotification('Sleep results shared successfully!', 'success');
        }).catch(() => {
            navigator.clipboard.writeText(shareText);
            showNotification('Sleep results copied to clipboard!', 'success');
        });
    } else {
        navigator.clipboard.writeText(shareText);
        showNotification('Sleep results copied to clipboard!', 'success');
    }
}

