// Generate AI Party Plan
function generateAIPartyPlan() {
    const age = document.getElementById('partyChildAge')?.value;
    const theme = document.getElementById('partyTheme')?.value;
    const guests = document.getElementById('partyGuestCount')?.value;
    const budget = document.getElementById('partyBudget')?.value;
    
    if (!age || !theme || !guests || !budget) {
        showNotification('Please fill in all party details', 'warning');
        return;
    }
    
    const recommendationsDiv = document.getElementById('aiPartyRecommendations');
    recommendationsDiv.innerHTML = '<div style="color: #666;">🤖 AI generating personalized party plan...</div>';
    
    // Simulate AI processing
    setTimeout(() => {
        const aiPlan = generateAIPartyPlanContent(age, theme, guests, budget);
        displayAIPartyPlan(aiPlan);
    }, 1500);
}

// Generate AI Party Plan Content
function generateAIPartyPlanContent(age, theme, guests, budget) {
    const themes = {
        princess: { activities: ['Royal crafts', 'Princess games', 'Story time'], food: ['Finger sandwiches', 'Fruit wands', 'Pink lemonade'] },
        superhero: { activities: ['Obstacle course', 'Superhero training', 'Rescue missions'], food: ['Hero sandwiches', 'Power smoothies', 'Sidekick snacks'] },
        sports: { activities: ['Sports tournaments', 'Team games', 'Medal ceremony'], food: ['Healthy snacks', 'Sports drinks', 'Victory pizza'] },
        animals: { activities: ['Petting zoo', 'Animal masks', 'Safari hunt'], food: ['Animal crackers', 'Jungle juice', 'Zebra cake'] }
    };
    
    const budgetPerGuest = Math.floor(budget / guests);
    const themeData = themes[theme] || themes.princess;
    
    return {
        theme: theme,
        age: age,
        guests: guests,
        budget: budget,
        budgetPerGuest: budgetPerGuest,
        activities: themeData.activities,
        food: themeData.food,
        decorations: ['Balloons', 'Streamers', 'Table settings', 'Party favors'],
        schedule: [
            { time: '2:00 PM', activity: 'Guests arrive, welcome activities' },
            { time: '3:00 PM', activity: 'Main games and activities' },
            { time: '4:00 PM', activity: 'Cake cutting and birthday song' },
            { time: '5:00 PM', activity: 'Gift opening and farewells' }
        ],
        aiInsights: [
            `Perfect ${theme} theme for ${age}-year-old!`,
            `Budget of $${budget} allows $${budgetPerGuest} per guest for premium experience`,
            `${guests} guests ideal for ${themeData.activities.length} planned activities`,
            'Consider dietary restrictions and allergies when planning food'
        ]
    };
}

