// Generate AI Travel Plan
function generateAITravelPlan() {
    const destination = document.getElementById('travelDestination')?.value;
    const kidsAges = document.getElementById('travelKidsAges')?.value;
    const duration = document.getElementById('travelDuration')?.value;
    
    if (!destination || !kidsAges || !duration) {
        showNotification('Please fill in all travel details', 'warning');
        return;
    }
    
    const recommendationsDiv = document.getElementById('aiTravelRecommendations');
    recommendationsDiv.innerHTML = '<div style="color: #666;">🤖 AI generating personalized travel plan...</div>';
    
    // Simulate AI processing
    setTimeout(() => {
        const aiPlan = generateAITravelPlanContent(destination, kidsAges, duration);
        displayAITravelPlan(aiPlan);
    }, 1500);
}

// Generate AI Travel Plan Content
function generateAITravelPlanContent(destination, kidsAges, duration) {
    const destinations = {
        beach: { activities: ['Beach games', 'Sandcastle building', 'Swimming', 'Shell collecting'], essentials: ['Sunscreen', 'Swimsuits', 'Beach toys', 'Cooler'] },
        mountains: { activities: ['Hiking', 'Nature walks', 'Wildlife spotting', 'Campfire stories'], essentials: ['Hiking boots', 'Warm layers', 'Binoculars', 'First aid kit'] },
        city: { activities: ['Museum tours', 'City exploration', 'Playgrounds', 'Local cuisine'], essentials: ['Comfortable shoes', 'Map', 'Camera', 'Snacks'] },
        theme_park: { activities: ['Ride adventures', 'Character meetings', 'Parade watching', 'Fireworks'], essentials: ['Autograph book', 'Comfortable clothes', 'Sun hat', 'Water bottle'] }
    };
    
    const destinationData = destinations[destination.toLowerCase()] || destinations.beach;
    const ageGroups = kidsAges.split(',').map(age => parseInt(age.trim()));
    
    return {
        destination: destination,
        kidsAges: ageGroups,
        duration: duration,
        activities: destinationData.activities,
        essentials: destinationData.essentials,
        packing: [
            'Weather-appropriate clothing for all family members',
            'Entertainment items for travel duration',
            'Snacks and water for kids',
            'First aid kit and medications',
            'Travel documents and insurance'
        ],
        aiInsights: [
            `Perfect ${destination} destination for families with ages ${kidsAges}!`,
            `${duration} trip ideal for ${ageGroups.length > 1 ? 'multiple age groups' : 'single age group'}`,
            'Consider travel insurance and emergency contacts',
            'Pack entertainment items for each age group'
        ]
    };
}

