// Generate AI Course Recommendations
function generateAICourseRecommendations() {
    const stage = document.getElementById('coursePregnancyStage')?.value;
    const goals = document.getElementById('courseLearningGoals')?.value;
    const time = document.getElementById('courseStudyTime')?.value;
    const style = document.getElementById('courseLearningStyle')?.value;
    
    if (!stage || !goals || !time || !style) {
        showNotification('Please complete all assessment questions', 'warning');
        return;
    }
    
    const recommendationsDiv = document.getElementById('aiCourseRecommendations');
    recommendationsDiv.innerHTML = '<div style="color: #666;">🤖 AI generating personalized course recommendations...</div>';
    
    // Simulate AI processing
    setTimeout(() => {
        const aiRecommendations = generateAICourseRecommendationsContent(stage, goals, time, style);
        displayAICourseRecommendations(aiRecommendations);
    }, 1500);
}

