// Generate AI Registry Suggestions Content
function generateAIRegistrySuggestionsContent(dueDate, budget, space, climate) {
    const budgetRanges = {
        budget: { priceRange: '$0-50', quality: 'Essential', brands: ['Gerber', 'Fisher-Price', 'Evenflo'] },
        mid: { priceRange: '$50-150', quality: 'Quality', brands: ['Graco', 'Chicco', 'Britax'] },
        premium: { priceRange: '$150-300', quality: 'Premium', brands: ['UPPAbaby', 'Stokke', 'Nuna'] },
        luxury: { priceRange: '$300+', quality: 'Luxury', brands: ['Bugaboo', 'Cybex', 'Silver Cross'] }
    };
    
    const spaceAdaptations = {
        apartment: { essentials: ['Compact gear', 'Space-saving solutions', 'Multi-functional items'] },
        house: { essentials: ['Full-size furniture', 'Standard gear', 'Room for expansion'] },
        small: { essentials: ['Minimalist approach', 'Foldable items', 'Vertical storage'] },
        large: { essentials: ['Standard gear', 'Multiple rooms', 'Dedicated spaces'] }
    };
    
    const climateEssentials = {
        cold: { clothing: 'Warm sleepers, layered outfits', gear: 'Heated items, warm blankets' },
        moderate: { clothing: 'Versatile layers, breathable fabrics', gear: 'Standard gear, all-season items' },
        warm: { clothing: 'Lightweight fabrics, sun protection', gear: 'Cooling items, breathable mesh' },
        hot: { clothing: 'Minimal clothing, cooling fabrics', gear: 'Air conditioning, cooling mats' }
    };
    
    const budgetData = budgetRanges[budget] || budgetRanges.mid;
    const spaceData = spaceAdaptations[space] || spaceAdaptations.house;
    const climateData = climateEssentials[climate] || climateEssentials.moderate;
    
    return {
        budget: budgetData,
        space: spaceData,
        climate: climateData,
        categories: [
            {
                name: 'Sleep Essentials',
                priority: 'Essential',
                items: ['Crib/Bassinet', 'Mattress', 'Bedding set', 'White noise machine'],
                aiReason: 'Critical for baby sleep and parent sanity'
            },
            {
                name: 'Feeding Supplies',
                priority: 'Essential',
                items: ['Bottles', 'Breast pump', 'Formula storage', 'High chair'],
                aiReason: 'Daily feeding needs regardless of feeding method'
            },
            {
                name: 'Diapering System',
                priority: 'Essential',
                items: ['Diapers', 'Wipes', 'Changing table', 'Diaper pail'],
                aiReason: 'Most frequently used items in first year'
            },
            {
                name: 'Travel Gear',
                priority: 'High',
                items: ['Car seat', 'Stroller', 'Baby carrier', 'Diaper bag'],
                aiReason: 'Safety and mobility essentials'
            },
            {
                name: 'Bathing & Care',
                priority: 'Medium',
                items: ['Baby tub', 'Hooded towels', 'Gentle soap', 'Nail clippers'],
                aiReason: 'Hygiene and comfort items'
            }
        ],
        aiInsights: [
            `Perfect ${budgetData.quality} quality for your budget range`,
            `${spaceData.essentials[0]} ideal for ${space} living`,
            `${climateData.clothing} recommended for ${climate} climate`,
            'AI predicts 15% savings with optimized registry'
        ]
    };
}

