// Generate AI Budget Analysis
function generateAIBudgetAnalysis() {
    const income = document.getElementById('monthlyIncome')?.value;
    const familySize = document.getElementById('familySize')?.value;
    
    if (!income || !familySize) {
        showNotification('Please complete all budget details', 'warning');
        return;
    }
    
    const analysisDiv = document.getElementById('aiBudgetAnalysis');
    analysisDiv.innerHTML = '<div style="color: #666;">💸 AI generating budget optimization...</div>';
    
    // Simulate AI processing
    setTimeout(() => {
        const budgetData = generateAIBudgetContent(income, familySize);
        displayAIBudgetAnalysis(budgetData);
    }, 1500);
}

// Generate AI Budget Content
function generateAIBudgetContent(income, familySize) {
    const recommendedBudget = {
        housing: Math.floor(income * 0.30),
        food: Math.floor(income * 0.15),
        transportation: Math.floor(income * 0.15),
        childcare: Math.floor(income * 0.20),
        healthcare: Math.floor(income * 0.08),
        savings: Math.floor(income * 0.12)
    };
    
    return {
        income: income,
        familySize: familySize,
        recommendedBudget: recommendedBudget,
        savingsPotential: Math.floor(income * 0.15),
        aiInsights: [
            `Optimal budget allocation for ${familySize}-person family`,
            `${recommendedBudget.savings} monthly savings potential identified`,
            'AI recommends automating savings transfers',
            'Consider reviewing subscriptions for optimization'
        ]
    };
}

