// Tips for Conception - Progress tracking
function updateTipProgress() {
    const tips = ['tip-intercourse', 'tip-lifestyle', 'tip-stress', 'tip-vitamins'];
    let completed = 0;
    
    tips.forEach(tipId => {
        const checkbox = document.getElementById(tipId);
        if (checkbox && checkbox.checked) {
            completed++;
            // Add completed class to parent
            checkbox.closest('.conception-tip-item')?.classList.add('completed');
        } else {
            // Remove completed class
            const parent = checkbox?.closest('.conception-tip-item');
            if (parent) parent.classList.remove('completed');
        }
    });
    
    // Update progress bar
    const progressPercent = (completed / tips.length) * 100;
    const progressBar = document.getElementById('tipsProgress');
    const progressText = document.getElementById('tipsProgressText');
    
    if (progressBar) {
        progressBar.style.width = progressPercent + '%';
    }
    
    if (progressText) {
        progressText.textContent = `${completed}/${tips.length} Completed`;
    }
    
    // Save to localStorage
    const tipProgress = {};
    tips.forEach(tipId => {
        const checkbox = document.getElementById(tipId);
        if (checkbox) {
            tipProgress[tipId] = checkbox.checked;
        }
    });
    try {
        localStorage.setItem('conceptionTipProgress', JSON.stringify(tipProgress));
    } catch (e) {
        console.warn('Failed to save tip progress:', e);
    }
    
    // Show celebration when all completed
    if (completed === tips.length) {
        showNotification('🎉 Congratulations! You\'ve completed all conception tips!', 'success');
    }
}

// Load tip progress from localStorage
function loadTipProgress() {
    try {
        const saved = localStorage.getItem('conceptionTipProgress');
        if (saved) {
            const tipProgress = JSON.parse(saved);
            Object.keys(tipProgress).forEach(tipId => {
                const checkbox = document.getElementById(tipId);
                if (checkbox) {
                    checkbox.checked = tipProgress[tipId];
                }
            });
            updateTipProgress();
        }
    } catch (e) {
        console.warn('Failed to load tip progress:', e);
    }
}

// Improved Fertility Tracker with data persistence
function saveFertilityData() {
    const date = document.getElementById('trackerDate')?.value;
    const temperature = document.getElementById('trackerTemperature')?.value;
    const mucus = document.getElementById('trackerMucus')?.value;
    
    // Get symptoms
    const symptoms = [];
    document.querySelectorAll('#fertilityTrackerModal .checkbox-group input:checked').forEach(checkbox => {
        symptoms.push(checkbox.parentElement.textContent.trim());
    });
    
    if (!date) {
        alert('Please enter today\'s date');
        return;
    }
    
    // Create entry object
    const entry = {
        date,
        temperature: temperature || null,
        mucus: mucus || null,
        symptoms,
        timestamp: new Date().toISOString()
    };
    
    // Load existing data
    let fertilityData = [];
    try {
        const saved = localStorage.getItem('fertilityTrackerData');
        if (saved) {
            fertilityData = JSON.parse(saved);
        }
    } catch (e) {
        console.warn('Failed to load fertility data:', e);
    }
    
    // Check if entry for this date already exists
    const existingIndex = fertilityData.findIndex(item => item.date === date);
    if (existingIndex >= 0) {
        fertilityData[existingIndex] = entry;
    } else {
        fertilityData.push(entry);
    }
    
    // Sort by date
    fertilityData.sort((a, b) => new Date(a.date) - new Date(b.date));
    
    // Save to localStorage
    try {
        localStorage.setItem('fertilityTrackerData', JSON.stringify(fertilityData));
    } catch (e) {
        console.warn('Failed to save fertility data:', e);
    }
    
    // Update the chart display
    updateFertilityChart(fertilityData);
    
    showNotification('Fertility data saved successfully!', 'success');
    closeFertilityTracker();
}

// Update fertility chart display
function updateFertilityChart(data) {
    const chartContainer = document.getElementById('trackerChart');
    if (!chartContainer) return;
    
    if (data.length === 0) {
        chartContainer.innerHTML = '<p>Track your daily symptoms to see your fertility pattern</p>';
        return;
    }
    
    // Get last 30 days of data
    const recentData = data.slice(-30);
    
    // Create a simple visual representation
    let html = '<div class="fertility-chart">';
    
    recentData.forEach(entry => {
        const tempClass = entry.temperature ? (entry.temperature > 98.4 ? 'high' : 'normal') : 'no-data';
        const mucusIcon = entry.mucus === 'eggwhite' ? '💧' : entry.mucus === 'watery' ? '💦' : entry.mucus ? '🔵' : '⚪';
        const symptomsCount = entry.symptoms ? entry.symptoms.length : 0;
        
        html += `
            <div class="chart-day">
                <div class="chart-date">${new Date(entry.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}</div>
                <div class="chart-temp temp-${tempClass}">${entry.temperature || '--'}</div>
                <div class="chart-mucus">${mucusIcon}</div>
                <div class="chart-symptoms">${symptomsCount > 0 ? '⚡' + symptomsCount : ''}</div>
            </div>
        `;
    });
    
    html += '</div>';
    
    // Add legend
    html += `
        <div class="chart-legend">
            <span>🌡️ Temperature: <span class="legend-high">High (>98.4°F)</span> <span class="legend-normal">Normal</span></span>
            <span>💧 Cervical Mucus: Egg White 💧 Watery 💦</span>
            <span>⚡ Symptoms</span>
        </div>
    `;
    
    chartContainer.innerHTML = html;
}

// Load fertility data on page load
function loadFertilityData() {
    try {
        const saved = localStorage.getItem('fertilityTrackerData');
        if (saved) {
            const fertilityData = JSON.parse(saved);
            updateFertilityChart(fertilityData);
        }
    } catch (e) {
        console.warn('Failed to load fertility data:', e);
    }
}

// Improved Pregnancy Test Calculator
function calculateTestDate() {
    const ovulationDate = document.getElementById('ovulationDateTest')?.value;
    
    if (!ovulationDate) {
        alert('Please enter your date of ovulation');
        return;
    }
    
    const ovulation = new Date(ovulationDate);
    
    // Calculate earliest test date (10 days after ovulation)
    const earliestTest = new Date(ovulation);
    earliestTest.setDate(earliestTest.getDate() + 10);
    
    // Calculate best test date (14 days after ovulation)
    const bestTest = new Date(ovulation);
    bestTest.setDate(bestTest.getDate() + 14);
    
    // Calculate most reliable test date (19 days after ovulation)
    const reliableTest = new Date(ovulation);
    reliableTest.setDate(reliableTest.getDate() + 19);
    
    // Update UI
    const earliestTestEl = document.getElementById('earliestTest');
    const bestTestEl = document.getElementById('bestTest');
    
    if (earliestTestEl) {
        earliestTestEl.textContent = earliestTest.toLocaleDateString('en-US', { 
            weekday: 'short', 
            month: 'short', 
            day: 'numeric' 
        });
    }
    
    if (bestTestEl) {
        bestTestEl.textContent = bestTest.toLocaleDateString('en-US', { 
            weekday: 'short', 
            month: 'short', 
            day: 'numeric' 
        });
    }
    
    // Add reliable test date if element exists
    let reliableTestEl = document.getElementById('reliableTest');
    if (!reliableTestEl) {
        // Create the element if it doesn't exist
        const resultBox = document.getElementById('testResult');
        if (resultBox) {
            const newItem = document.createElement('div');
            newItem.className = 'result-item';
            newItem.innerHTML = `
                <span class="result-label">Most Reliable Test Date:</span>
                <span class="result-value highlight" id="reliableTest">--</span>
            `;
            resultBox.appendChild(newItem);
            reliableTestEl = document.getElementById('reliableTest');
        }
    }
    
    if (reliableTestEl) {
        reliableTestEl.textContent = reliableTest.toLocaleDateString('en-US', { 
            weekday: 'short', 
            month: 'short', 
            day: 'numeric' 
        });
    }
    
    showNotification('Test dates calculated successfully!', 'success');
}

function escapeHTML(value) {
    return String(value ?? '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

// ADMIN PANEL CONTROLLER
const adminPanelState = {
    ready: false,
    currentView: 'dashboard',
    users: [],
    dashboard: null
};

function getAdminApiBase() {
    if (window.BACKEND_API && typeof window.BACKEND_API.getBaseUrl === 'function') {
        return window.BACKEND_API.getBaseUrl();
    }
    return window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1'
        ? 'http://localhost:5000'
        : window.location.origin;
}

async function adminRequest(endpoint, options = {}) {
    const response = await fetch(`${getAdminApiBase()}${endpoint}`, {
        credentials: 'include',
        headers: {
            'Content-Type': 'application/json',
            ...(options.headers || {})
        },
        ...options
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
        throw new Error(data.error || `Admin request failed (${response.status})`);
    }
    return data;
}

function initializeAdminPanel() {
    adminPanelState.ready = true;
    adminSetStatus('Checking admin session...');
    adminRequest('/api/admin-panel/me')
        .then((data) => {
            adminShowWorkspace(data.admin);
            adminLoadDashboard();
        })
        .catch(() => {
            adminShowLogin();
            adminSetStatus('');
        });
}

function adminShowLogin() {
    const login = document.getElementById('adminLoginPanel');
    const workspace = document.getElementById('adminWorkspace');
    if (login) login.hidden = false;
    if (workspace) workspace.hidden = true;
}

function adminShowWorkspace(admin) {
    const login = document.getElementById('adminLoginPanel');
    const workspace = document.getElementById('adminWorkspace');
    if (login) login.hidden = true;
    if (workspace) workspace.hidden = false;
    const title = document.getElementById('adminPageTitle');
    if (title && admin?.name) title.textContent = `Welcome, ${admin.name}`;
}

function adminSetStatus(message, type = 'info') {
    const status = document.getElementById('adminStatus');
    if (!status) return;
    status.textContent = message || '';
    status.className = `admin-status ${message ? 'show' : ''} ${type}`;
}

async function adminLogin(event) {
    event.preventDefault();
    const username = document.getElementById('adminEmail')?.value.trim();
    const password = document.getElementById('adminPassword')?.value;
    try {
        adminSetStatus('Signing in...');
        const data = await adminRequest('/api/admin-panel/login', {
            method: 'POST',
            body: JSON.stringify({ username, password })
        });
        adminShowWorkspace(data.admin);
        adminSetStatus('Admin login successful.', 'success');
        adminSetView('dashboard');
        showNotification('Admin panel unlocked', 'success');
    } catch (error) {
        adminSetStatus(error.message, 'error');
        showNotification(error.message, 'error');
    }
}

async function adminLogout() {
    try {
        await adminRequest('/api/admin-panel/logout', { method: 'POST', body: '{}' });
    } catch (error) {
        console.warn('Admin logout warning:', error);
    }
    adminShowLogin();
    adminSetStatus('Logged out.', 'success');
}

function adminSetView(view) {
    adminPanelState.currentView = view;
    document.querySelectorAll('.admin-nav').forEach((btn) => {
        btn.classList.toggle('active', btn.dataset.adminView === view);
    });
    document.querySelectorAll('.admin-view').forEach((panel) => {
        panel.classList.toggle('active', panel.id === `adminView-${view}`);
    });
    const label = {
        dashboard: 'Admin Dashboard',
        users: 'User Management',
        ai: 'AI Chat Monitoring',
        help: 'Help Requests',
        emergency: 'Emergency Management',
        content: 'Content Management',
        notifications: 'Notifications & Announcements',
        reports: 'Reports & Analytics',
        settings: 'System Settings'
    }[view] || 'Admin Panel';
    const title = document.getElementById('adminPageTitle');
    if (title) title.textContent = label;
    adminLoadCurrentView();
}

function adminLoadCurrentView() {
    const loaders = {
        dashboard: adminLoadDashboard,
        users: adminLoadUsers,
        ai: adminLoadAiChats,
        help: adminLoadHelpRequests,
        emergency: adminLoadEmergencies,
        content: adminLoadContent,
        notifications: () => adminSetStatus('Compose and send an announcement.', 'info'),
        reports: adminLoadReports,
        settings: () => adminSetStatus('System settings loaded.', 'success')
    };
    const loader = loaders[adminPanelState.currentView];
    if (loader) loader();
}

async function adminLoadDashboard() {
    try {
        adminSetStatus('Loading dashboard...');
        const data = await adminRequest('/api/admin-panel/dashboard');
        adminPanelState.dashboard = data;
        adminRenderStats(data.stats || {});
        adminRenderFeed(data.recentEvents || data.recentActivity || []);
        adminSetStatus('Dashboard updated from MongoDB.', 'success');
    } catch (error) {
        adminSetStatus(error.message, 'error');
    }
}

function adminRenderStats(stats) {
    const target = document.getElementById('adminStats');
    if (!target) return;
    const cards = [
        ['Total Users', stats.totalUsers || 0, 'Registered accounts'],
        ['Active Mothers', stats.activeMothers || 0, 'Pregnancy profiles'],
        ['AI Chats', stats.aiChats || 0, 'Chatbot interactions'],
        ['Emergencies', stats.emergencyReports || stats.emergencies || 0, 'Safety signals'],
        ['Help Requests', stats.helpRequests || 0, 'Support queue'],
        ['Notifications', stats.notificationsSent || stats.notifications || 0, 'Messages sent']
    ];
    target.innerHTML = cards.map(([title, value, meta]) => `
        <article class="admin-stat-card">
            <span>${title}</span>
            <strong>${value}</strong>
            <small>${meta}</small>
        </article>
    `).join('');
}

function adminRenderFeed(items) {
    const target = document.getElementById('adminActivityFeed');
    if (!target) return;
    if (!items.length) {
        target.innerHTML = '<p class="admin-empty">No recent activity recorded yet.</p>';
        return;
    }
    target.innerHTML = items.map((item) => `
        <div class="admin-feed-item">
            <strong>${escapeHTML(item.action || item.type || 'Activity')}</strong>
            <span>${escapeHTML(item.collection || item.userId || 'System')}</span>
            <small>${adminFormatDate(item.createdAt || item.savedAt)}</small>
        </div>
    `).join('');
}

async function adminLoadUsers() {
    try {
        adminSetStatus('Loading users...');
        const data = await adminRequest('/api/admin-panel/users');
        adminPanelState.users = data.users || [];
        adminRenderUsers(adminPanelState.users);
        adminSetStatus('Users loaded.', 'success');
    } catch (error) {
        adminSetStatus(error.message, 'error');
    }
}

function adminFilterUsers() {
    const query = (document.getElementById('adminUserSearch')?.value || '').toLowerCase();
    const filtered = adminPanelState.users.filter((user) => {
        return [user.name, user.email, user.status, user.pregnancy_week, user.pregnancyWeek]
            .filter(Boolean)
            .some((value) => String(value).toLowerCase().includes(query));
    });
    adminRenderUsers(filtered);
}

function adminRenderUsers(users) {
    const target = document.getElementById('adminUsersTable');
    if (!target) return;
    if (!users.length) {
        target.innerHTML = '<p class="admin-empty">No users matched.</p>';
        return;
    }
    target.innerHTML = `
        <table class="admin-table">
            <thead><tr><th>Name</th><th>Email</th><th>Week</th><th>Status</th><th>Joined</th><th>Action</th></tr></thead>
            <tbody>
                ${users.map((user) => {
                    const id = user._id || user.id || '';
                    const status = user.status || 'active';
                    return `
                        <tr>
                            <td>${escapeHTML(user.name || 'Mother')}</td>
                            <td>${escapeHTML(user.email || user.userId || 'Unknown')}</td>
                            <td>${escapeHTML(user.pregnancy_week || user.pregnancyWeek || '--')}</td>
                            <td><span class="admin-pill ${status}">${escapeHTML(status)}</span></td>
                            <td>${adminFormatDate(user.createdAt || user.savedAt)}</td>
                            <td><button type="button" onclick="adminToggleUserStatus('${id}', '${status}')">${status === 'suspended' ? 'Activate' : 'Suspend'}</button></td>
                        </tr>
                    `;
                }).join('')}
            </tbody>
        </table>
    `;
}

async function adminToggleUserStatus(id, currentStatus) {
    if (!id) return;
    const nextStatus = currentStatus === 'suspended' ? 'active' : 'suspended';
    try {
        await adminRequest(`/api/admin-panel/users/${id}/status`, {
            method: 'PATCH',
            body: JSON.stringify({ status: nextStatus })
        });
        showNotification(`User marked ${nextStatus}`, 'success');
        adminLoadUsers();
    } catch (error) {
        showNotification(error.message, 'error');
    }
}

async function adminLoadAiChats() {
    try {
        adminSetStatus('Loading AI chat logs...');
        const data = await adminRequest('/api/admin-panel/ai-chats');
        const target = document.getElementById('adminAiLogs');
        const chats = data.chats || [];
        if (!target) return;
        target.innerHTML = chats.length ? chats.map((chat) => {
            const question = chat.question || chat.message || chat.userMessage || 'AI interaction';
            const dangerous = /bleeding|pain|emergency|medicine|medication|dizzy|faint|headache|movement/i.test(question);
            return `
                <div class="admin-feed-item ${dangerous ? 'danger' : ''}">
                    <strong>${escapeHTML(question)}</strong>
                    <span>${escapeHTML(chat.response || chat.answer || 'Response saved in chat history')}</span>
                    <small>${adminFormatDate(chat.createdAt || chat.savedAt)}</small>
                </div>
            `;
        }).join('') : '<p class="admin-empty">No AI chat history is stored yet.</p>';
        adminSetStatus('AI logs loaded.', 'success');
    } catch (error) {
        adminSetStatus(error.message, 'error');
    }
}

async function adminLoadHelpRequests() {
    try {
        adminSetStatus('Loading help requests...');
        const data = await adminRequest('/api/admin-panel/help-requests');
        const requests = data.requests || [];
        const target = document.getElementById('adminHelpRequests');
        if (!target) return;
        target.innerHTML = requests.length ? `
            <table class="admin-table">
                <thead><tr><th>User</th><th>Issue</th><th>Urgency</th><th>Status</th><th>Date</th></tr></thead>
                <tbody>
                    ${requests.map((request) => `
                        <tr>
                            <td>${escapeHTML(request.name || request.userId || 'Mother')}</td>
                            <td>${escapeHTML(request.problem || request.issue || request.message || 'Support request')}</td>
                            <td><span class="admin-pill ${String(request.urgency || 'normal').toLowerCase()}">${escapeHTML(request.urgency || 'Normal')}</span></td>
                            <td>${escapeHTML(request.status || 'Pending')}</td>
                            <td>${adminFormatDate(request.createdAt || request.savedAt)}</td>
                        </tr>
                    `).join('')}
                </tbody>
            </table>
        ` : '<p class="admin-empty">No help requests have been submitted yet.</p>';
        adminSetStatus('Help requests loaded.', 'success');
    } catch (error) {
        adminSetStatus(error.message, 'error');
    }
}

async function adminLoadEmergencies() {
    await adminLoadHelpRequests();
    const target = document.getElementById('adminEmergencyList');
    try {
        const data = await adminRequest('/api/admin-panel/events');
        const items = (data.events || []).filter((event) => /emergency|urgent|bleeding|pain|ambulance/i.test(JSON.stringify(event))).slice(0, 12);
        if (!target) return;
        target.innerHTML = items.length ? items.map((item) => `
            <div class="admin-feed-item danger">
                <strong>${escapeHTML(item.action || item.type || 'Emergency signal')}</strong>
                <span>${escapeHTML(item.userId || item.collection || 'System')}</span>
                <small>${adminFormatDate(item.createdAt || item.savedAt)}</small>
            </div>
        `).join('') : '<p class="admin-empty">No emergency signals recorded.</p>';
    } catch (error) {
        adminSetStatus(error.message, 'error');
    }
}

function adminLoadContent() {
    const target = document.getElementById('adminContentList');
    if (!target) return;
    const drafts = JSON.parse(localStorage.getItem('adminArticleDrafts') || '[]');
    target.innerHTML = drafts.length ? drafts.map((draft) => `
        <div class="admin-feed-item">
            <strong>${escapeHTML(draft.title)}</strong>
            <span>${escapeHTML(draft.category)}</span>
            <small>${adminFormatDate(draft.createdAt)}</small>
        </div>
    `).join('') : '<p class="admin-empty">No admin article drafts yet.</p>';
    adminSetStatus('Content manager ready.', 'success');
}

async function adminSaveContent(event) {
    event.preventDefault();
    const draft = {
        title: document.getElementById('adminArticleTitle')?.value.trim(),
        category: document.getElementById('adminArticleCategory')?.value,
        content: document.getElementById('adminArticleContent')?.value.trim(),
        createdAt: new Date().toISOString()
    };
    const drafts = JSON.parse(localStorage.getItem('adminArticleDrafts') || '[]');
    drafts.unshift(draft);
    localStorage.setItem('adminArticleDrafts', JSON.stringify(drafts.slice(0, 20)));
    event.target.reset();
    adminLoadContent();
    if (window.DB_SYNC && typeof window.DB_SYNC.saveActivity === 'function') {
        window.DB_SYNC.saveActivity({ type: 'admin-content', id: `article-${Date.now()}`, label: draft.title, category: draft.category });
    }
    showNotification('Article draft saved', 'success');
}

async function adminSendNotification(event) {
    event.preventDefault();
    const payload = {
        title: document.getElementById('adminNoticeTitle')?.value.trim(),
        message: document.getElementById('adminNoticeMessage')?.value.trim(),
        audience: document.getElementById('adminNoticeAudience')?.value || 'all'
    };
    try {
        await adminRequest('/api/admin-panel/notifications', {
            method: 'POST',
            body: JSON.stringify(payload)
        });
        event.target.reset();
        showNotification('Notification sent and stored in MongoDB', 'success');
        adminSetStatus('Notification sent.', 'success');
    } catch (error) {
        showNotification(error.message, 'error');
        adminSetStatus(error.message, 'error');
    }
}

function adminLoadReports() {
    if (adminPanelState.dashboard?.stats) {
        const reports = document.getElementById('adminReportsGrid');
        if (reports) {
            reports.innerHTML = Object.entries(adminPanelState.dashboard.stats).map(([key, value]) => `
                <article class="admin-stat-card">
                    <span>${escapeHTML(key.replace(/([A-Z])/g, ' $1'))}</span>
                    <strong>${value}</strong>
                    <small>Current total</small>
                </article>
            `).join('');
        }
        adminDrawMiniChart(adminPanelState.dashboard.stats);
    } else {
        adminLoadDashboard().then(adminLoadReports);
    }
}

function adminDrawMiniChart(stats) {
    const canvas = document.getElementById('adminMiniChart');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const entries = Object.entries(stats).slice(0, 6);
    const max = Math.max(...entries.map(([, value]) => Number(value) || 0), 1);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#f8fbff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    entries.forEach(([key, value], index) => {
        const x = 45 + index * 135;
        const height = ((Number(value) || 0) / max) * 160 + 10;
        ctx.fillStyle = ['#2f80ed', '#14b8a6', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'][index];
        ctx.fillRect(x, 210 - height, 70, height);
        ctx.fillStyle = '#243447';
        ctx.font = '14px Arial';
        ctx.fillText(String(value), x + 20, 190 - height);
        ctx.font = '12px Arial';
        ctx.fillText(key.replace(/([A-Z])/g, ' $1').slice(0, 14), x - 12, 235);
    });
}

function adminExportReport() {
    const report = {
        exportedAt: new Date().toISOString(),
        dashboard: adminPanelState.dashboard,
        users: adminPanelState.users
    };
    const blob = new Blob([JSON.stringify(report, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `mamasafe-admin-report-${Date.now()}.json`;
    link.click();
    URL.revokeObjectURL(url);
}

function adminFormatDate(value) {
    if (!value) return 'Not recorded';
    const date = new Date(value);
    return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleString();
}

